insert into public.library_materials (code, parent_code, name_en, name_fil, description_en, description_fil, resin_code, default_bin, sort_order) values
  ('PLA', null, 'Plastics', 'Plastik', 'Bottles, containers, bags and packaging. The resin code tells you what it is.', 'Bote, lalagyan, supot at pakete. Sinasabi ng resin code kung anong plastik ito.', null, null, 10),
  ('PAP', null, 'Paper & cardboard', 'Papel at karton', 'Clean, dry paper and cardboard are recyclable. Wet, waxed or food-soiled paper is not.', 'Nare-recycle ang malinis at tuyong papel at karton. Hindi ang basa, may wax o may pagkain.', null, 'recyclable', 20),
  ('MET', null, 'Metals', 'Metal', 'Cans, foil and scrap. Metals keep their value and junk shops buy most of them.', 'Lata, foil at scrap. May halaga ang metal at binibili ng junk shop.', null, 'recyclable', 30),
  ('GLA', null, 'Glass', 'Salamin', 'Bottles and jars are recyclable. Window glass, mirrors and broken glass need care.', 'Nare-recycle ang bote at garapon. Mag-ingat sa salamin ng bintana, salamin at basag.', null, 'recyclable', 40),
  ('CER', null, 'Ceramics & porcelain', 'Seramika at porselana', 'Plates, mugs, tiles and pots. Ceramics don''t melt with glass, so they go in residual.', 'Pinggan, tasa, tisa at paso. Hindi natutunaw kasama ng bote ang seramika, kaya residual.', null, 'residual', 50),
  ('TEX', null, 'Textiles & footwear', 'Tela at sapatos', 'Clothes, linens, shoes and bags. Reuse and donation come first.', 'Damit, kumot, sapatos at bag. Unahin ang paggamit ulit at pag-donate.', null, 'residual', 60),
  ('ELE', null, 'Electronics (e-waste)', 'Elektroniks (e-waste)', 'Anything with a plug, battery or circuit board. E-waste goes to registered collectors.', 'Anumang may saksakan, baterya o circuit board. Sa rehistradong kolektor ang e-waste.', null, 'hazardous', 70),
  ('BAT', null, 'Batteries', 'Baterya', 'All batteries are special waste. Never put them in a bin loose.', 'Special waste ang lahat ng baterya. Huwag ilagay nang maluwag sa basurahan.', null, 'hazardous', 80),
  ('LIG', null, 'Lighting', 'Ilaw at bombilya', 'Bulbs and tubes. Fluorescent lamps contain mercury and need special handling.', 'Bombilya at tubo. May mercury ang fluorescent at kailangan ng espesyal na paghawak.', null, 'hazardous', 90),
  ('ORG', null, 'Organics', 'Nabubulok', 'Food scraps and garden waste. Compost them or use the green bin.', 'Tirang pagkain at dahon. I-compost o ilagay sa berdeng basurahan.', null, 'biodegradable', 100),
  ('WOO', null, 'Wood & natural', 'Kahoy at natural', 'Wood, bamboo and cork. Untreated pieces can be reused or composted.', 'Kahoy, kawayan at cork. Puwedeng gamitin ulit o i-compost ang hindi pininturahan.', null, 'biodegradable', 110),
  ('RUB', null, 'Rubber & foam', 'Goma at foam', 'Rubber, foam and tires. Hard to recycle, so reuse comes first.', 'Goma, foam at gulong. Mahirap i-recycle, kaya unahin ang paggamit ulit.', null, 'residual', 120),
  ('CMP', null, 'Composites & multilayer', 'Halo-halong materyales', 'Items made of layers that can''t be separated, like cartons and pouches.', 'Gamit na gawa sa patong-patong na hindi mapaghiwalay, tulad ng karton at pouch.', null, 'residual', 130),
  ('MED', null, 'Medical & sanitary', 'Medikal at pangkalinisan', 'Medicine, sharps and sanitary items. Sharps and medicine need special handling.', 'Gamot, karayom at pangkalinisan. Kailangan ng espesyal na paghawak ang karayom at gamot.', null, 'residual', 140),
  ('HHW', null, 'Household hazardous', 'Mapanganib sa bahay', 'Paints, chemicals, pesticides and oils. Keep them in their containers for hazardous collection.', 'Pintura, kemikal, pesticide at langis. Iwan sa lalagyan para sa koleksyon ng mapanganib.', null, 'hazardous', 150),
  ('BLK', null, 'Bulky & special', 'Malalaki at espesyal', 'Furniture, mattresses, appliances and debris too big for household bins.', 'Muwebles, kutson, appliance at debris na masyadong malaki para sa basurahan.', null, 'residual', 160),
  ('PLA-1', 'PLA', '#1 PET', '#1 PET', 'Clear drink bottles. Widely bought by junk shops when clean.', 'Malinaw na bote ng inumin. Binibili ng junk shop kapag malinis.', 1, 'recyclable', 11),
  ('PLA-2', 'PLA', '#2 HDPE', '#2 HDPE', 'Stiff, opaque bottles like shampoo and detergent. Recyclable when clean.', 'Matigas at malabong bote tulad ng shampoo at sabon. Nare-recycle kapag malinis.', 2, 'recyclable', 12),
  ('PLA-3', 'PLA', '#3 PVC', '#3 PVC', 'Pipes, hoses and some blister packs. Rarely recycled.', 'Tubo, hose at ilang blister pack. Bihirang ma-recycle.', 3, 'residual', 13),
  ('PLA-4', 'PLA', '#4 LDPE', '#4 LDPE', 'Soft bags and squeeze bottles. Accepted by some programmes when clean and dry.', 'Malambot na supot at bote. Tinatanggap ng ilang programa kapag malinis at tuyo.', 4, 'residual', 14),
  ('PLA-5', 'PLA', '#5 PP', '#5 PP', 'Food tubs, caps and microwavable boxes. Recyclable when clean.', 'Lalagyan ng pagkain, takip at microwavable. Nare-recycle kapag malinis.', 5, 'recyclable', 15),
  ('PLA-6', 'PLA', '#6 PS and styrofoam', '#6 PS at styrofoam', 'Styrofoam and hard clear cups. Usually residual.', 'Styro at matigas na malinaw na baso. Kadalasang residual.', 6, 'residual', 16),
  ('PLA-7', 'PLA', '#7 Other plastics', '#7 Iba pang plastik', 'Mixed or other resins. Usually residual unless a programme accepts them.', 'Halo o ibang resin. Kadalasang residual maliban kung may programa.', 7, 'residual', 17),
