insert into public.library_items (slug, name_en, name_fil, aliases, material_code, resin_code, bin, summary_en, summary_fil, prep_en, prep_fil, note_en, note_fil, dont_en, dont_fil, hazard_en, hazard_fil, value, reuse_en, reuse_fil, reduce_en, reduce_fil, fact_en, fact_fil, related, detectable_class_key, sources, status, reviewed_by, reviewed_at) values
  ('aa-battery', 'AA or AAA battery', 'AA o AAA na baterya', array['aa battery', 'aaa battery', 'double a', 'triple a', 'baterya ng remote', 'alkaline', 'heavy duty']::text[], 'BAT-ALK', null, 'hazardous', 'Tape the ends and keep used batteries in a closed jar. Bring them to the red bin or a battery drop-off.', 'Takpan ng tape ang dulo at itabi sa saradong garapon. Dalhin sa pulang basurahan o battery drop-off.', '[{"title": "Tape the ends", "detail": "Cover the terminals so they can''t spark."}, {"title": "Keep them dry", "detail": "Store used batteries in a closed container."}, {"title": "Bring them in", "detail": "Red bin or a battery drop-off."}]'::jsonb, '[{"title": "Takpan ng tape ang dulo", "detail": "Takpan ang terminal para walang kislap."}, {"title": "Panatilihing tuyo", "detail": "Itabi ang gamit na baterya sa saradong lalagyan."}, {"title": "Dalhin", "detail": "Sa pulang basurahan o battery drop-off."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Old batteries can leak corrosive chemicals and can short-circuit and heat up if the ends touch metal.', 'Puwedeng tumagas ang kemikal ng lumang baterya at uminit kapag nagdikit ang dulo sa metal.', null, '{}'::text[], '{}'::text[], array['Use rechargeable batteries']::text[], array['Gumamit ng rechargeable na baterya']::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['battery', 'rechargeable-battery']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('acetone', 'Nail polish remover (acetone)', 'Acetone', array['acetone', 'nail polish remover', 'remover']::text[], 'HHW-COSM', null, 'hazardous', 'Keep it capped and bring leftovers to hazardous waste collection.', 'Panatilihing nakatakip at dalhin ang natira sa koleksyon ng mapanganib.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Acetone is highly flammable.', 'Napakadaling magliyab ng acetone.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['nail-polish']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('aircon', 'Air conditioner', 'Aircon', array['aircon', 'ac', 'air conditioner', 'split type', 'window type']::text[], 'BLK-APPL', null, 'hazardous', 'Have a technician remove it and recover the gas, then use take-back or an e-waste collector.', 'Ipaalis sa technician at ipabawi ang gas, saka gamitin ang take-back o e-waste collector.', '[{"title": "Call a technician", "detail": "They recover the refrigerant gas safely."}, {"title": "Arrange pickup", "detail": "Store take-back or e-waste collector."}]'::jsonb, '[{"title": "Tumawag ng technician", "detail": "Ligtas nilang binabawi ang refrigerant gas."}, {"title": "Magpakuha", "detail": "Take-back ng tindahan o e-waste collector."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Appliances contain electronics, metals and, in cooling appliances, refrigerant gases that must not be released.', 'May electronics at metal ang appliance, at may refrigerant gas ang pampalamig na hindi dapat pakawalan.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['refrigerator']::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('aluminum-can', 'Aluminum can', 'Lata', array['can', 'soda can', 'softdrinks can', 'beer can', 'lata', 'tin can']::text[], 'MET-AL', null, 'recyclable', 'Empty it and crush it, then drop it in the blue bin.', 'Ubusin at pisain, saka ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Make sure no drink is left inside."}, {"title": "Crush it", "detail": "Step on it or squeeze it to save space."}, {"title": "Sort it", "detail": "Drop it in the blue bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Siguraduhing wala nang laman."}, {"title": "Pisain", "detail": "Tapakan o pisain para makatipid ng lugar."}, {"title": "Ilagay", "detail": "Sa asul na basurahan."}]'::jsonb, 'Empty it fully before sorting.', 'Ubusin muna ang laman bago itapon.', '{}'::text[], '{}'::text[], null, null, 'buys', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Aluminum can be recycled again and again without losing quality.', 'Puwedeng i-recycle nang paulit-ulit ang aluminyo nang hindi bumababa ang kalidad.', '{}'::text[], 'aluminum_can', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('aluminum-foil', 'Aluminum foil', 'Aluminum foil', array['foil', 'tin foil', 'aluminum foil', 'palara']::text[], 'MET-FOIL', null, 'recyclable', 'Wipe it clean and scrunch it into a ball for the blue bin. Greasy foil goes in the black bin.', 'Punasan at buuin nang pabilog para sa asul. Ang may mantikang foil ay sa itim.', '[{"title": "Clean it", "detail": "Wipe off food and grease."}, {"title": "Ball it up", "detail": "Scrunch it into a fist-size ball."}]'::jsonb, '[{"title": "Linisin", "detail": "Punasan ang pagkain at mantika."}, {"title": "Buuin", "detail": "Buuin nang kasinlaki ng kamao."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Wash and reuse it for cooking']::text[], array['Hugasan at gamitin ulit sa pagluluto']::text[], '{}'::text[], '{}'::text[], null, null, array['foil-tray', 'snack-wrapper']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('balloon', 'Balloon', 'Lobo', array['lobo', 'balloon', 'party balloon', 'foil balloon']::text[], 'RUB-RUB', null, 'residual', 'Pop it and put it in the black bin. Never release balloons outdoors.', 'Paputukin at ilagay sa itim na basurahan. Huwag pakawalan ang lobo sa labas.', '[{"title": "Deflate it", "detail": "Cut it so it can''t float away."}, {"title": "Sort it", "detail": "Black bin, with its ribbon."}]'::jsonb, '[{"title": "Paputukin", "detail": "Gupitin para hindi lumipad."}, {"title": "Itapon", "detail": "Sa itim, kasama ang tali."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Decorate with paper or cloth instead']::text[], array['Magdekorasyon gamit ang papel o tela']::text[], null, null, array['rubber-band']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('bamboo-skewer', 'Chopsticks / bamboo skewer', 'Barbecue stick', array['chopsticks', 'skewer', 'barbecue stick', 'bbq stick', 'toothpick']::text[], 'WOO-RAW', null, 'biodegradable', 'Break sharp tips, then place it in the green bin.', 'Baliin ang matulis na dulo, saka ilagay sa berdeng basurahan.', '[]'::jsonb, '[]'::jsonb, 'Plastic chopsticks go in the black bin.', 'Ang plastik na chopsticks ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Untreated bamboo and wood break down naturally.', 'Kusang nabubulok ang kawayan at kahoy na walang pintura.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('banana-peel', 'Banana peel', 'Balat ng saging', array['banana', 'peel', 'fruit peel', 'saging', 'balat ng saging']::text[], 'ORG-FOOD', null, 'biodegradable', 'Remove stickers, then compost or use the green bin.', 'Tanggalin ang sticker, saka i-compost o ilagay sa berdeng basurahan.', '[{"title": "Remove stickers", "detail": "Fruit stickers are plastic and go in the black bin."}, {"title": "Compost or green bin", "detail": "Add it to a compost pile or the green bin."}]'::jsonb, '[{"title": "Tanggalin ang sticker", "detail": "Plastik ang sticker at sa itim na basurahan ito."}, {"title": "I-compost", "detail": "Ilagay sa compost o berdeng basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Organic material breaks down naturally.', 'Kusang nabubulok ang organikong basura.', '{}'::text[], 'banana_peel', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('bandage', 'Bandage or plaster', 'Benda o band-aid', array['bandaid', 'band-aid', 'bandage', 'plaster', 'gasa']::text[], 'MED-SAN', null, 'residual', 'Wrap used bandages in paper and put them in the black bin.', 'Balutin sa papel ang gamit na benda at ilagay sa itim na basurahan.', '[{"title": "Wrap it", "detail": "Paper or a small bag."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Balutin", "detail": "Papel o maliit na supot."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['cotton-buds']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('battery', 'Battery', 'Baterya', array['batteries', 'aa battery', 'aaa battery', 'baterya', 'lithium battery', 'battery cell']::text[], 'BAT-ALK', null, 'hazardous', 'Tape the terminals. Take it to a battery collection point.', 'Takpan ng tape ang dulo. Dalhin sa koleksyon ng baterya.', '[{"title": "Tape the terminals", "detail": "Cover both ends with tape to prevent sparks."}, {"title": "Bring it to a collection point", "detail": "Use the red bin or a battery drop-off."}]'::jsonb, '[{"title": "Takpan ng tape", "detail": "Lagyan ng tape ang magkabilang dulo para walang kislap."}, {"title": "Dalhin sa koleksyon", "detail": "Gamitin ang pulang basurahan o battery drop-off."}]'::jsonb, 'Never mix with regular waste. Batteries can leak or start fires.', 'Huwag ihalo sa ordinaryong basura. Puwedeng tumagas o magliyab ang baterya.', '{}'::text[], '{}'::text[], 'Batteries can leak harmful chemicals. Lithium-ion batteries can catch fire if crushed or punctured.', 'Puwedeng tumagas ang mapanganib na kemikal ng baterya. Ang lithium-ion ay puwedeng magliyab kapag nadurog o nabutas.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Batteries can leak or start fires. Never mix with regular waste.', 'Puwedeng tumagas o magliyab ang baterya. Huwag itong ihalo sa ordinaryong basura.', '{}'::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('bedsheet', 'Bedsheet or curtain', 'Kumot, punda o kurtina', array['kumot', 'punda', 'bedsheet', 'curtain', 'kurtina', 'pillowcase']::text[], 'TEX-HOME', null, 'residual', 'Donate clean ones or sew them into bags and rags. The black bin is the last stop.', 'I-donate ang malinis o tahiin bilang bag at basahan. Ang itim ang huling destinasyon.', '[{"title": "Wash it", "detail": "Clean before giving away."}, {"title": "Donate or reuse", "detail": "Sew into bags, covers or rags."}]'::jsonb, '[{"title": "Labhan", "detail": "Linisin bago ibigay."}, {"title": "I-donate o gamitin", "detail": "Tahiin bilang bag, takip o basahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away', 'Sew it into shopping bags']::text[], array['Kung magagamit pa, ipamigay o i-donate', 'Tahiin bilang shopping bag']::text[], '{}'::text[], '{}'::text[], null, null, array['towel']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('bicycle-tube', 'Bicycle tire or inner tube', 'Gulong o interior ng bisikleta', array['bicycle tire', 'inner tube', 'interior', 'bike tire']::text[], 'RUB-TIRE', null, 'residual', 'Patch punctures first. Old inner tubes make strong straps; worn ones go in the black bin.', 'Tapalan muna ang butas. Nagagawang matibay na tali ang lumang interior; ang sira ay sa itim.', '[{"title": "Patch it", "detail": "Bike shops patch tubes cheaply."}, {"title": "Reuse or sort", "detail": "Cut into straps, or black bin."}]'::jsonb, '[{"title": "Tapalan", "detail": "Mura ang pagtapal sa bike shop."}, {"title": "Gamitin o itapon", "detail": "Gupitin bilang tali, o sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Cut it into strong rubber straps']::text[], array['Gupitin para maging matibay na tali']::text[], '{}'::text[], '{}'::text[], null, null, array['car-tire', 'rubber-band']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('bleach', 'Bleach', 'Bleach / Zonrox', array['bleach', 'chlorine', 'zonrox', 'clorox']::text[], 'HHW-CHEM', null, 'hazardous', 'Use it up as directed. Leftover bleach goes to hazardous waste collection in its bottle.', 'Gamitin ayon sa direksyon. Ang natira ay dalhin sa koleksyon ng mapanganib, nasa bote nito.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Bleach mixed with acids or ammonia releases toxic gas.', 'Naglalabas ng nakalalasong gas ang bleach kapag nahaluan ng asido o ammonia.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['muriatic-acid']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('blister-pack', 'Empty blister pack', 'Walang lamang blister pack', array['blister pack', 'medicine foil', 'tablet strip', 'banig ng gamot']::text[], 'CMP-BLISTER', null, 'residual', 'Empty blister packs are plastic and foil together. Put them in the black bin.', 'Pinagsamang plastik at foil ang walang lamang blister pack. Ilagay sa itim na basurahan.', '[{"title": "Make sure it''s empty", "detail": "Leftover tablets follow the medicine rules."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Siguraduhing walang laman", "detail": "Ang natirang tableta ay sundin ang patakaran sa gamot."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['expired-medicine']::text[], 'expired_medicine', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('bones', 'Bones and shells', 'Buto at kabibe', array['buto', 'chicken bones', 'fish bones', 'shells', 'kabibe', 'crab shell']::text[], 'ORG-BONE', null, 'biodegradable', 'Bones and seafood shells go in the green bin. They break down slowly, so skip small home composts.', 'Ang buto at kabibe ay sa berdeng basurahan. Mabagal silang mabulok kaya huwag sa maliit na compost.', '[{"title": "Scrape off food", "detail": "Wrap them in paper to avoid smell."}, {"title": "Sort it", "detail": "Green bin."}]'::jsonb, '[{"title": "Alisin ang laman", "detail": "Balutin sa papel para hindi mangamoy."}, {"title": "Itapon", "detail": "Sa berdeng basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['food-scraps', 'eggshell']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('broken-dishware', 'Broken plates and cups', 'Basag na pinggan at tasa', array['basag na pinggan', 'broken plate', 'broken cup', 'sirang plato']::text[], 'CER-DISH', null, 'residual', 'Wrap the pieces well, label BASAG and put them in the black bin, never loose.', 'Balutin nang mabuti ang piraso, lagyan ng BASAG at ilagay sa itim, hindi kailanman nang walang balot.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, 'Sharp pieces injure waste collectors.', 'Nasusugatan ang mga nangongolekta ng basura sa matatalim na piraso.', '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['broken-glass', 'ceramic-plate']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('broken-fluorescent', 'Broken fluorescent lamp', 'Basag na fluorescent', array['broken fluorescent', 'broken cfl', 'basag na ilaw']::text[], 'LIG-FLUO', null, 'hazardous', 'Open windows and leave the room for 15 minutes. Then collect the pieces with stiff paper into a sealed jar.', 'Buksan ang bintana at lumabas nang 15 minuto. Saka ipunin ang piraso gamit ang matigas na papel sa saradong garapon.', '[{"title": "Air it out", "detail": "Open windows, leave for 15 minutes, keep kids and pets away."}, {"title": "Collect, don''t vacuum", "detail": "Use stiff paper and sticky tape for small bits."}, {"title": "Seal it", "detail": "Put everything in a sealed jar for hazardous collection."}]'::jsonb, '[{"title": "Pahanginan", "detail": "Buksan ang bintana, lumabas nang 15 minuto, ilayo ang bata at alaga."}, {"title": "Ipunin, huwag i-vacuum", "detail": "Gumamit ng matigas na papel at tape sa maliliit."}, {"title": "Isara", "detail": "Ilagay lahat sa saradong garapon para sa koleksyon."}]'::jsonb, null, null, array['Don''t use a vacuum cleaner or broom']::text[], array['Huwag gumamit ng vacuum o walis']::text[], 'A broken lamp releases mercury vapour and sharp glass.', 'Naglalabas ng singaw ng mercury at matalim na salamin ang basag na ilaw.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Philippine rules on lamp waste require producers and LGUs to set up collection for mercury-containing lamps.', 'May patakaran sa Pilipinas na nag-aatas sa mga gumagawa at LGU na mangolekta ng ilaw na may mercury.', array['fluorescent-tube', 'broken-glass']::text[], 'light_bulb', array['S-RA9003-22', 'S-RA9003-3PP', 'S-JAO-LAMPS']::text[], 'draft', '{}'::text[], null),
  ('broken-glass', 'Broken glass', 'Basag na salamin', array['glass shards', 'bubog', 'basag', 'broken bottle']::text[], 'GLA-BROKEN', null, 'residual', 'Wrap it well and label it "sharp". Give it to staff.', 'Balutin nang mabuti at lagyan ng "BASAG". Ibigay sa staff.', '[]'::jsonb, '[]'::jsonb, 'Never put loose broken glass in any bin.', 'Huwag kailanman ilagay ang basag na salamin nang walang balot sa basurahan.', '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Loose broken glass injures waste workers.', 'Nasusugatan ang mga nangongolekta ng basura dahil sa basag na salaming walang balot.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('broom-stick', 'Old broom (walis tingting)', 'Lumang walis tingting', array['walis tingting', 'walis tambo', 'broom', 'old broom']::text[], 'WOO-RAW', null, 'biodegradable', 'Natural brooms go in the green bin. Remove plastic handles and wire first.', 'Ang natural na walis ay sa berde. Tanggalin muna ang plastik na hawakan at alambre.', '[{"title": "Remove plastic and wire", "detail": "These go to the black bin or scrap metal."}, {"title": "Sort it", "detail": "Green bin."}]'::jsonb, '[{"title": "Tanggalin ang plastik at alambre", "detail": "Sa itim o scrap na metal ang mga ito."}, {"title": "Itapon", "detail": "Sa berdeng basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['leaves']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('bubble-wrap', 'Bubble wrap', 'Bubble wrap', array['bubble wrap', 'air bubble plastic', 'packing plastic']::text[], 'PLA-FILM', null, 'residual', 'Keep it and reuse it for packing. When it''s torn, put it in the black bin.', 'Itabi at gamitin ulit sa pag-iimpake. Kapag punit na, ilagay sa itim na basurahan.', '[{"title": "Keep it", "detail": "Fold it and store it for your next parcel."}, {"title": "Sort when torn", "detail": "Put it in the black bin."}]'::jsonb, '[{"title": "Itabi", "detail": "Itupi at itago para sa susunod na padala."}, {"title": "Itapon kapag punit", "detail": "Ilagay sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Reuse it for packing', 'Wrap fragile items when moving']::text[], array['Gamitin ulit sa pag-iimpake', 'Pambalot ng babasagin kapag lilipat']::text[], '{}'::text[], '{}'::text[], null, null, array['courier-pouch', 'cardboard']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('button-cell', 'Button or coin battery', 'Button na baterya', array['button battery', 'coin battery', 'watch battery', 'cr2032', 'lr44', 'relo battery']::text[], 'BAT-BTN', null, 'hazardous', 'Tape both sides, keep them away from children, and bring them to battery collection.', 'Takpan ng tape ang magkabilang side, ilayo sa bata, at dalhin sa koleksyon ng baterya.', '[{"title": "Tape the ends", "detail": "Cover the terminals so they can''t spark."}, {"title": "Keep them dry", "detail": "Store used batteries in a closed container."}, {"title": "Bring them in", "detail": "Red bin or a battery drop-off."}]'::jsonb, '[{"title": "Takpan ng tape ang dulo", "detail": "Takpan ang terminal para walang kislap."}, {"title": "Panatilihing tuyo", "detail": "Itabi ang gamit na baterya sa saradong lalagyan."}, {"title": "Dalhin", "detail": "Sa pulang basurahan o battery drop-off."}]'::jsonb, 'If a child swallows one, go to a hospital immediately.', 'Kapag may batang nakalunok, dalhin agad sa ospital.', '{}'::text[], '{}'::text[], 'Swallowed button batteries can cause serious internal burns in children within hours. Some contain mercury.', 'Puwedeng makapinsala nang malubha sa loob ng katawan ng bata ang nalunok na button battery. May mercury ang ilan.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['calculator', 'aa-battery']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('cabinet', 'Cabinet or shelf', 'Aparador o istante', array['aparador', 'cabinet', 'shelf', 'istante', 'drawer']::text[], 'BLK-FURN', null, 'residual', 'Sell, donate or repair it. Otherwise, take it apart and ask for bulky pickup.', 'Ibenta, i-donate o ipaayos. Kung hindi, baklasin at itanong ang bulky pickup.', '[{"title": "Try to reuse it", "detail": "Donate, sell or repair first."}, {"title": "Ask for pickup", "detail": "Your barangay or city schedules bulky-waste collection."}]'::jsonb, '[{"title": "Subukang gamitin ulit", "detail": "I-donate, ibenta o ipaayos muna."}, {"title": "Magpakuha", "detail": "Ang barangay o lungsod ang nag-iiskedyul ng bulky pickup."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['wooden-chair']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('calculator', 'Calculator or small gadget', 'Calculator o maliit na gadget', array['calculator', 'digital watch', 'toy with battery', 'remote', 'gadget']::text[], 'ELE-SMALL', null, 'hazardous', 'Take out the battery, then bring both to an e-waste or battery drop-off.', 'Alisin ang baterya, saka dalhin pareho sa e-waste o battery drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['button-cell', 'remote-control']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('car-battery', 'Car or motorcycle battery', 'Baterya ng sasakyan o motor', array['car battery', 'motorcycle battery', 'lead acid battery', 'batirya ng kotse']::text[], 'BAT-PB', null, 'hazardous', 'Battery shops take old car batteries when you buy a new one, and many junk shops buy them.', 'Tinatanggap ng battery shop ang lumang baterya kapag bumili ka ng bago, at binibili rin ng ilang junk shop.', '[{"title": "Keep it upright", "detail": "Don''t tip it over; it contains acid."}, {"title": "Bring it in", "detail": "Trade it in at a battery shop."}]'::jsonb, '[{"title": "Panatilihing nakatayo", "detail": "Huwag itumba; may asido ito."}, {"title": "Dalhin", "detail": "Ipagpalit sa battery shop."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Lead-acid batteries contain lead and sulfuric acid that burn skin and poison soil and water.', 'May lead at sulfuric acid ang baterya ng sasakyan na nakapapaso sa balat at lumalason sa lupa at tubig.', 'buys', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['motor-oil']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('car-tire', 'Car or motorcycle tire', 'Gulong ng sasakyan o motor', array['gulong', 'tire', 'tyre', 'interior', 'spare tire']::text[], 'RUB-TIRE', null, 'residual', 'Leave old tires at the shop when you buy new ones. Never burn tires.', 'Iwan ang lumang gulong sa shop kapag bumili ng bago. Huwag kailanman sunugin ang gulong.', '[{"title": "Leave it at the shop", "detail": "Vulcanizing and tire shops collect old tires."}, {"title": "Or reuse it", "detail": "Planters, playgrounds, bumpers."}]'::jsonb, '[{"title": "Iwan sa shop", "detail": "Nangongolekta ng lumang gulong ang vulcanizing at tire shop."}, {"title": "O gamitin ulit", "detail": "Taniman, palaruan, bumper."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, null, array['Make it into a planter or swing']::text[], array['Gawing taniman o duyan']::text[], '{}'::text[], '{}'::text[], 'Open burning of waste, including tires, is banned under RA 9003.', 'Bawal ang pagsusunog ng basura, kasama ang gulong, sa ilalim ng RA 9003.', array['bicycle-tube']::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('cardboard', 'Cardboard', 'Karton', array['box', 'carton', 'karton', 'kahon', 'pizza box']::text[], 'PAP-BOARD', null, 'recyclable', 'Flatten it and keep it dry. Place it in the blue bin.', 'Itupi at panatilihing tuyo. Ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Remove any contents, plastic wrap or foam."}, {"title": "Flatten it", "detail": "Open the flaps and fold it flat."}, {"title": "Keep it dry", "detail": "Put it in the blue bin away from wet waste."}]'::jsonb, '[{"title": "Alisin ang laman", "detail": "Tanggalin ang laman, plastic wrap o foam."}, {"title": "Itupi", "detail": "Buksan ang flaps at itupi nang patag."}, {"title": "Panatilihing tuyo", "detail": "Ilagay sa asul na basurahan, malayo sa basang basura."}]'::jsonb, 'Wet or greasy cardboard (e.g. pizza box bottom) goes in the black bin.', 'Ang basa o may mantikang karton (hal. ilalim ng pizza box) ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, 'buys', array['Reuse it for storage or packing.']::text[], array['Gamitin ulit para sa pag-iimbak o pagpapadala.']::text[], '{}'::text[], '{}'::text[], 'Dry cardboard is easy to recycle into new boxes. Wet or greasy cardboard is not.', 'Madaling gawing bagong kahon ang tuyong karton. Hindi na ang basa o may mantika.', '{}'::text[], 'cardboard', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('carpet', 'Carpet or rug', 'Karpet o alpombra', array['carpet', 'rug', 'doormat', 'alpombra', 'basahan sa pinto']::text[], 'BLK-FURN', null, 'residual', 'Donate clean rugs. Cut old carpet into pieces for the black bin, or ask for bulky pickup.', 'I-donate ang malinis na alpombra. Gupitin ang lumang karpet para sa itim, o itanong ang bulky.', '[{"title": "Try to reuse it", "detail": "Donate, sell or repair first."}, {"title": "Ask for pickup", "detail": "Your barangay or city schedules bulky-waste collection."}]'::jsonb, '[{"title": "Subukang gamitin ulit", "detail": "I-donate, ibenta o ipaayos muna."}, {"title": "Magpakuha", "detail": "Ang barangay o lungsod ang nag-iiskedyul ng bulky pickup."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Cut it into mats for pets or the garage']::text[], array['Gupitin bilang sapin ng alaga o garahe']::text[], '{}'::text[], '{}'::text[], null, null, array['t-shirt']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('ceramic-figurine', 'Ceramic figurine or decor', 'Ceramic na palamuti', array['figurine', 'ceramic decor', 'santo', 'estatwa', 'palamuti']::text[], 'CER-DISH', null, 'residual', 'Donate whole pieces. Wrap broken ceramics in paper, label them and use the black bin.', 'I-donate ang buo. Balutin sa papel ang basag, lagyan ng label at ilagay sa itim.', '[{"title": "Donate if whole", "detail": "Thrift shops and churches often take decor."}, {"title": "Wrap broken pieces", "detail": "Newspaper, then label BASAG."}]'::jsonb, '[{"title": "I-donate kung buo", "detail": "Madalas tumanggap ang ukay at simbahan ng palamuti."}, {"title": "Balutin ang basag", "detail": "Diyaryo, saka lagyan ng label na BASAG."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use broken pieces as drainage in plant pots']::text[], array['Gamiting pang-drainage sa paso ang basag']::text[], '{}'::text[], '{}'::text[], null, null, array['broken-dishware', 'ceramic-vase']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('ceramic-mug', 'Ceramic mug', 'Tasa (seramika)', array['mug', 'tasa', 'coffee mug', 'ceramic cup']::text[], 'CER-DISH', null, 'residual', 'Ceramics aren''t glass. Donate whole mugs; wrap broken ones, label BASAG and use the black bin.', 'Hindi salamin ang seramika. I-donate ang buo; balutin ang basag, lagyan ng BASAG at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, 'A common mistake: ceramics in the glass bin ruin glass recycling.', 'Karaniwang mali: nasisira ang pag-recycle ng salamin kapag nahaluan ng seramika.', '{}'::text[], '{}'::text[], null, null, 'none', array['Use it as a pen holder or plant pot', 'If it''s still usable, donate it or give it away']::text[], array['Gamitin bilang lalagyan ng ballpen o paso', 'Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['drinking-glass', 'ceramic-plate', 'plastic-cup']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('ceramic-plate', 'Ceramic plate', 'Pinggan (seramika)', array['plate', 'pinggan', 'plato', 'dinner plate', 'saucer']::text[], 'CER-DISH', null, 'residual', 'Donate whole plates. Wrap broken ones, label BASAG and put them in the black bin.', 'I-donate ang buong pinggan. Balutin ang basag, lagyan ng BASAG at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['ceramic-mug', 'porcelain-bowl']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('ceramic-spoon', 'Ceramic soup spoon', 'Kutsarang seramika', array['soup spoon', 'chinese spoon', 'ceramic spoon']::text[], 'CER-DISH', null, 'residual', 'Wrap broken ceramic spoons and put them in the black bin.', 'Balutin ang basag na kutsarang seramika at ilagay sa itim na basurahan.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['ceramic-plate']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('ceramic-vase', 'Ceramic vase or figurine', 'Plorera o palamuting seramika', array['vase', 'figurine', 'plorera', 'display', 'ceramic decor']::text[], 'CER-DISH', null, 'residual', 'Donate whole pieces. Wrap broken ones, label BASAG and put them in the black bin.', 'I-donate ang buo. Balutin ang basag, lagyan ng BASAG at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['ceramic-mug']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('cereal-box', 'Cereal or snack box', 'Kahon ng cereal o biskwit', array['cereal box', 'biscuit box', 'medicine box', 'shoe box', 'paperboard', 'manipis na karton']::text[], 'PAP-BOARD', null, 'recyclable', 'Remove the plastic liner, flatten the box and put it in the blue bin.', 'Tanggalin ang plastik sa loob, itupi ang kahon at ilagay sa asul na basurahan.', '[{"title": "Remove the liner", "detail": "The inner plastic bag goes in the black bin."}, {"title": "Flatten it", "detail": "Open the ends and press it flat."}]'::jsonb, '[{"title": "Tanggalin ang liner", "detail": "Ang plastik sa loob ay sa itim na basurahan."}, {"title": "Itupi", "detail": "Buksan ang dulo at pindutin nang patag."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Use it for files, drawer dividers or crafts']::text[], array['Gamitin sa files, divider ng drawer o crafts']::text[], '{}'::text[], '{}'::text[], null, null, array['cardboard', 'snack-wrapper']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('cfl-bulb', 'CFL bulb', 'CFL na bombilya', array['cfl', 'energy saving bulb', 'spiral bulb', 'compact fluorescent']::text[], 'LIG-FLUO', null, 'hazardous', 'Keep it whole, wrap it in its box, and bring it to a lamp take-back or hazardous collection.', 'Huwag basagin, balutin sa kahon, at dalhin sa lamp take-back o koleksyon ng mapanganib.', '[{"title": "Keep it whole", "detail": "Don''t break it."}, {"title": "Wrap it", "detail": "Use its box or thick paper."}, {"title": "Bring it in", "detail": "Lamp take-back or hazardous waste collection."}]'::jsonb, '[{"title": "Huwag basagin", "detail": "Hawakan nang maingat."}, {"title": "Balutin", "detail": "Gamitin ang kahon nito o makapal na papel."}, {"title": "Dalhin", "detail": "Sa lamp take-back o koleksyon ng mapanganib na basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Fluorescent tubes and CFLs contain mercury. A broken lamp releases mercury vapour.', 'May mercury ang fluorescent at CFL. Naglalabas ng singaw ng mercury ang basag na ilaw.', null, '{}'::text[], '{}'::text[], array['Switch to LED bulbs, which have no mercury']::text[], array['Lumipat sa LED, na walang mercury']::text[], 'Philippine rules on lamp waste require producers and LGUs to set up collection for mercury-containing lamps.', 'May patakaran sa Pilipinas na nag-aatas sa mga gumagawa at LGU na mangolekta ng ilaw na may mercury.', array['light-bulb', 'led-bulb']::text[], 'light_bulb', array['S-RA9003-22', 'S-RA9003-3PP', 'S-JAO-LAMPS']::text[], 'draft', '{}'::text[], null),
  ('charger-cable', 'Charger or cable', 'Charger o kable', array['charger', 'cable', 'usb cable', 'adapter', 'extension cord', 'wire']::text[], 'ELE-CABLE', null, 'hazardous', 'Keep chargers and cables together and bring them to an e-waste drop-off.', 'Pagsama-samahin ang charger at kable at dalhin sa e-waste drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['mobile-phone', 'scrap-wire']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('chip-canister', 'Chip canister', 'Lata ng chips', array['pringles can', 'chips tube', 'snack canister']::text[], 'CMP-MIXED', null, 'residual', 'Canisters mix cardboard, foil and metal. Reuse them for storage, then use the black bin.', 'Halo-halong karton, foil at metal ang lata ng chips. Gamitin ulit, saka sa itim.', '[{"title": "Empty it", "detail": "Shake out crumbs."}, {"title": "Reuse or sort", "detail": "Storage, then the black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ipagpag ang mumo."}, {"title": "Gamitin o itapon", "detail": "Lalagyan, saka sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Store pencils, straws or spaghetti']::text[], array['Lagyan ng lapis, straw o spaghetti']::text[], '{}'::text[], '{}'::text[], null, null, array['snack-wrapper']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('christmas-lights', 'Christmas lights', 'Christmas lights', array['christmas lights', 'string lights', 'fairy lights', 'pailaw']::text[], 'LIG-STRING', null, 'hazardous', 'Replace a blown bulb or fuse first. Broken sets go to an e-waste drop-off.', 'Palitan muna ang pundidong bombilya o fuse. Ang sira ay sa e-waste drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Light strings contain wiring, solder and small electronics.', 'May kable, solder at maliliit na electronics ang pailaw.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['charger-cable']::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('cigarette-butt', 'Cigarette butt', 'Upos', array['cigarette', 'upos', 'yosi', 'filter']::text[], 'PLA-7', 7, 'residual', 'Make sure it is fully out, then place it in the black bin.', 'Siguraduhing patay na, saka ilagay sa itim na basurahan.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Filters are plastic and contain toxins.', 'Plastik ang filter at may lason ito.', '{}'::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('clay-pot', 'Clay or terracotta pot', 'Paso o palayok', array['paso', 'palayok', 'clay pot', 'terracotta', 'banga']::text[], 'CER-POT', null, 'residual', 'Use broken pots as drainage in other pots. Otherwise, wrap and put them in the black bin.', 'Gamitin ang basag na paso bilang drainage sa ibang paso. Kung hindi, balutin at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Put broken pieces at the bottom of plant pots for drainage']::text[], array['Ilagay ang basag sa ilalim ng paso para sa drainage']::text[], '{}'::text[], '{}'::text[], null, null, array['ceramic-plate']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('coconut-shell', 'Coconut shell or husk', 'Bao o bunot ng niyog', array['bao', 'bunot', 'coconut husk', 'coconut shell', 'niyog']::text[], 'WOO-RAW', null, 'biodegradable', 'Coconut shells and husks go in the green bin, or give them away for crafts and gardening.', 'Ang bao at bunot ay sa berde, o ipamigay para sa crafts at paghahalaman.', '[{"title": "Clean it", "detail": "Scrape out the meat."}, {"title": "Use or sort it", "detail": "Gardeners use husks; otherwise, green bin."}]'::jsonb, '[{"title": "Linisin", "detail": "Kayurin ang laman."}, {"title": "Gamitin o itapon", "detail": "Ginagamit ng hardinero ang bunot; kung hindi, sa berde."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use husks as plant potting material', 'Use shells as bowls or for crafts']::text[], array['Gamitin ang bunot sa paso', 'Gawing mangkok o crafts ang bao']::text[], '{}'::text[], '{}'::text[], null, null, array['leaves']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('coffee-capsule', 'Coffee capsule', 'Coffee capsule', array['coffee pod', 'capsule', 'nespresso', 'dolce gusto']::text[], 'CMP-MIXED', null, 'residual', 'Empty the grounds into the green bin. Some brands take back capsules; otherwise, black bin.', 'Ilagay ang sapal sa berde. May brand na tumatanggap ng capsule; kung hindi, sa itim.', '[{"title": "Empty it", "detail": "Coffee grounds go in the green bin."}, {"title": "Check for take-back", "detail": "Ask where you bought them."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ang sapal ay sa berdeng basurahan."}, {"title": "Alamin ang take-back", "detail": "Itanong kung saan binili."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Use a refillable capsule or ground coffee']::text[], array['Gumamit ng refillable na capsule o giniling na kape']::text[], null, null, array['coffee-grounds']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('coffee-grounds', 'Coffee grounds', 'Sapal ng kape', array['coffee', 'grounds', 'kape', 'tea leaves']::text[], 'ORG-FOOD', null, 'biodegradable', 'Place them in the green bin or compost.', 'Ilagay sa berdeng basurahan o i-compost.', '[]'::jsonb, '[]'::jsonb, 'Coffee pods and sachets go in the black bin.', 'Ang coffee pod at sachet ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, null, array['Use them as garden fertilizer.']::text[], array['Gamitin bilang pataba sa halaman.']::text[], '{}'::text[], '{}'::text[], 'Coffee grounds are organic and compost well.', 'Organiko ang sapal ng kape at madaling i-compost.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('computer-mouse', 'Computer mouse or keyboard', 'Mouse o keyboard', array['mouse', 'keyboard', 'computer accessories', 'webcam']::text[], 'ELE-ACC', null, 'hazardous', 'Donate working ones; bring broken ones to an e-waste drop-off.', 'I-donate ang gumagana; dalhin ang sira sa e-waste drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['laptop']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('condensed-milk-can', 'Milk can', 'Lata ng gatas', array['evaporated milk can', 'condensed milk can', 'powdered milk can', 'lata ng gatas']::text[], 'MET-FE', null, 'recyclable', 'Rinse out the milk, then put it in the blue bin or sell it to a junk shop.', 'Banlawan ang gatas, saka ilagay sa asul o ibenta sa junk shop.', '[{"title": "Rinse it", "detail": "Milk left inside smells and attracts ants."}, {"title": "Remove the label", "detail": "Paper labels can go with paper."}]'::jsonb, '[{"title": "Banlawan", "detail": "Mabaho at nilalanggam ang natirang gatas."}, {"title": "Tanggalin ang label", "detail": "Puwedeng isama sa papel ang label."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'buys', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['sardine-can']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('construction-rubble', 'Construction rubble', 'Debris ng konstruksyon', array['debris', 'rubble', 'hollow blocks', 'cement', 'graba', 'renovation waste']::text[], 'BLK-CONST', null, 'residual', 'Rubble doesn''t go in household bins. Ask your barangay about debris collection or a hauler.', 'Hindi sa basurahan ng bahay ang debris. Itanong sa barangay ang koleksyon o hauler.', '[{"title": "Sort it", "detail": "Keep metal, wood and rubble apart."}, {"title": "Bag or pile it", "detail": "Use sacks; keep it off the road."}, {"title": "Ask for collection", "detail": "Barangay or a licensed hauler."}]'::jsonb, '[{"title": "Ihiwalay", "detail": "Paghiwalayin ang metal, kahoy at debris."}, {"title": "Isako o iipon", "detail": "Gumamit ng sako; huwag sa daan."}, {"title": "Magpakolekta", "detail": "Barangay o lisensyadong hauler."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Clean rubble can be used as fill for garden paths']::text[], array['Puwedeng pang-tambak sa daanan sa hardin ang malinis na debris']::text[], '{}'::text[], '{}'::text[], null, null, array['floor-tile', 'toilet-bowl', 'pvc-pipe']::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('cooking-oil-bottle', 'Cooking oil bottle', 'Bote ng mantika', array['oil bottle', 'bote ng mantika', 'cooking oil container']::text[], 'PLA-1', 1, 'recyclable', 'Drain it, wash it with soap, let it dry, then put it in the blue bin.', 'Patuluin, hugasan ng sabon at patuyuin, saka ilagay sa asul na basurahan.', '[{"title": "Drain it", "detail": "Let the last drops drip into a used can, not the sink."}, {"title": "Wash it", "detail": "Use dishwashing soap to remove the oil."}, {"title": "Dry it", "detail": "Oily bottles spoil other recyclables."}]'::jsonb, '[{"title": "Patuluin", "detail": "Patuluin ang huling patak sa lumang lata, hindi sa lababo."}, {"title": "Hugasan", "detail": "Gumamit ng dishwashing soap para matanggal ang mantika."}, {"title": "Patuyuin", "detail": "Nakasisira ng ibang recyclable ang bote na may mantika."}]'::jsonb, 'If you can''t get the oil out, put it in the black bin.', 'Kung hindi matanggal ang mantika, ilagay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, 'accepts', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['used-cooking-oil', 'plastic-bottle']::text[], 'plastic_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-STD-RIC']::text[], 'draft', '{}'::text[], null),
  ('cork-stopper', 'Cork stopper', 'Tapon na cork', array['cork', 'wine cork', 'tapon']::text[], 'WOO-CORK', null, 'biodegradable', 'Natural cork goes in the green bin. Plastic corks go in the black bin.', 'Ang natural na cork ay sa berde. Ang plastik na cork ay sa itim.', '[{"title": "Check it", "detail": "Natural cork is light and crumbly."}, {"title": "Sort it", "detail": "Green bin."}]'::jsonb, '[{"title": "Suriin", "detail": "Magaan at madurog ang natural na cork."}, {"title": "Itapon", "detail": "Sa berdeng basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use corks as pin boards or plant markers']::text[], array['Gawing pin board o marker ng halaman']::text[], '{}'::text[], '{}'::text[], null, null, array['liquor-bottle']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('cotton-buds', 'Cotton buds and cotton balls', 'Cotton buds at bulak', array['cotton buds', 'q-tips', 'cotton balls', 'bulak']::text[], 'MED-SAN', null, 'residual', 'Used cotton goes in the black bin. Never flush it.', 'Ang gamit na bulak ay sa itim. Huwag kailanman i-flush.', '[{"title": "Sort it", "detail": "Black bin."}, {"title": "Don''t flush it", "detail": "Cotton clogs pipes."}]'::jsonb, '[{"title": "Itapon", "detail": "Sa itim na basurahan."}, {"title": "Huwag i-flush", "detail": "Bumabara ang bulak sa tubo."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Choose paper-stem cotton buds or reusable cloths']::text[], array['Pumili ng cotton buds na papel ang tangkay o tela']::text[], null, null, array['used-tissue']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('courier-pouch', 'Online shopping plastic pouch', 'Plastik na pakete ng online order', array['courier bag', 'shopee pouch', 'lazada pouch', 'parcel plastic', 'mailer bag', 'poly mailer']::text[], 'PLA-FILM', null, 'residual', 'Remove labels and tape, keep it clean, and bring it to a plastic collection programme or put it in the black bin.', 'Tanggalin ang label at tape, panatilihing malinis, at dalhin sa programa ng plastik o ilagay sa itim.', '[{"title": "Empty it", "detail": "Take out all paper and fillers."}, {"title": "Remove tape and labels", "detail": "Peel off as much as you can."}, {"title": "Keep it", "detail": "Collect clean pouches for a programme, or use the black bin."}]'::jsonb, '[{"title": "Ubusin ang laman", "detail": "Alisin ang papel at palaman."}, {"title": "Tanggalin ang tape at label", "detail": "Tanggalin hangga''t kaya."}, {"title": "Itabi", "detail": "Ipunin ang malinis para sa programa, o ilagay sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Reuse it to send your own parcels']::text[], array['Gamitin ulit sa sarili mong padala']::text[], '{}'::text[], '{}'::text[], 'Under the EPR Act (RA 11898), large companies must recover the plastic packaging they put on the market.', 'Sa ilalim ng EPR Act (RA 11898), kailangang bawiin ng malalaking kumpanya ang plastik na packaging nila.', array['plastic-bag', 'bubble-wrap']::text[], null, array['S-RA9003-22', 'S-QC-T2C', 'S-RA11898']::text[], 'draft', '{}'::text[], null),
  ('diaper', 'Diaper', 'Lampin', array['diaper', 'nappy', 'lampin', 'adult diaper']::text[], 'MED-SAN', null, 'residual', 'Roll it up and tape it, then place it in the black bin.', 'Irolyo at lagyan ng tape, saka ilagay sa itim na basurahan.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Diapers are sanitary waste and can''t be recycled or composted.', 'Sanitary waste ang lampin kaya hindi ito nire-recycle o kino-compost.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('disposable-gloves', 'Disposable gloves', 'Disposable na gloves', array['latex gloves', 'nitrile gloves', 'surgical gloves', 'food gloves']::text[], 'MED-PPE', null, 'residual', 'Peel them off inside out and put them in the black bin.', 'Hubarin nang baligtad at ilagay sa itim na basurahan.', '[{"title": "Remove inside out", "detail": "Keep the dirty side in."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Hubarin nang baligtad", "detail": "Nasa loob ang maruming bahagi."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['face-mask', 'rubber-gloves']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('drinking-glass', 'Drinking glass', 'Baso (salamin)', array['baso', 'drinking glass', 'tumbler glass', 'glassware']::text[], 'GLA-HEAT', null, 'residual', 'Drinking glasses melt differently from bottles. Donate whole ones; wrap broken ones for the black bin.', 'Iba ang pagkatunaw ng baso sa bote. I-donate ang buo; balutin ang basag para sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, 'Don''t put drinking glasses in the blue bin with bottles and jars.', 'Huwag ilagay ang baso sa asul kasama ng bote at garapon.', '{}'::text[], '{}'::text[], null, null, 'none', array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['glass-jar', 'ceramic-mug']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('e-waste', 'E-waste (phones, cables, chargers)', 'E-waste', array['phone', 'cellphone', 'charger', 'cable', 'earphones', 'electronics', 'gadget']::text[], 'ELE-SMALL', null, 'hazardous', 'Do not throw it in any bin. Bring it to an e-waste collection point.', 'Huwag itapon sa kahit anong basurahan. Dalhin sa e-waste collection point.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Electronics contain metals and chemicals that are harmful but valuable to recover.', 'May mga metal at kemikal sa electronics na mapanganib pero may halaga kapag nabawi.', '{}'::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('earphones', 'Earphones or headphones', 'Earphones o headphones', array['earphones', 'headset', 'headphones', 'earbuds']::text[], 'ELE-ACC', null, 'hazardous', 'Bring old earphones to an e-waste drop-off. Wireless ones have a battery inside.', 'Dalhin ang lumang earphones sa e-waste drop-off. May baterya sa loob ang wireless.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['charger-cable']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('egg-tray', 'Egg tray', 'Lalagyan ng itlog', array['egg tray', 'egg carton', 'paper egg tray', 'karton ng itlog']::text[], 'PAP-BOARD', null, 'recyclable', 'Paper egg trays go in the blue bin, or tear them up for compost. Plastic trays go in the black bin.', 'Ang papel na egg tray ay sa asul, o pirasuhin para sa compost. Ang plastik ay sa itim.', '[{"title": "Check the material", "detail": "Paper or plastic?"}, {"title": "Paper", "detail": "Blue bin, or tear into compost."}, {"title": "Plastic", "detail": "Black bin."}]'::jsonb, '[{"title": "Alamin ang materyal", "detail": "Papel o plastik?"}, {"title": "Papel", "detail": "Sa asul, o pirasuhin para sa compost."}, {"title": "Plastik", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Use it as a seedling starter', 'Give it back to your egg seller']::text[], array['Gamitin bilang punlaan', 'Ibalik sa tindera ng itlog']::text[], '{}'::text[], '{}'::text[], null, null, array['cardboard', 'eggshell']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('eggshell', 'Eggshell', 'Balat ng itlog', array['egg', 'egg shell', 'itlog', 'balat ng itlog']::text[], 'ORG-BONE', null, 'biodegradable', 'Place it in the green bin or compost.', 'Ilagay sa berdeng basurahan o i-compost.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Crushed eggshells are good for garden soil.']::text[], array['Mabuti sa lupa ng halaman ang dinurog na balat ng itlog.']::text[], '{}'::text[], '{}'::text[], 'Eggshells are organic and add calcium to compost.', 'Organiko ang balat ng itlog at nagdadagdag ito ng calcium sa compost.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('electric-fan', 'Electric fan', 'Electric fan', array['electric fan', 'bentilador', 'stand fan', 'desk fan']::text[], 'ELE-LARGE', null, 'hazardous', 'A repair shop can often fix it. Otherwise, bring it to an e-waste collector or junk shop that takes appliances.', 'Kadalasang naaayos ito sa repair shop. Kung hindi, dalhin sa e-waste collector o junk shop na tumatanggap ng appliance.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['rice-cooker']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('eraser', 'Eraser', 'Pambura', array['eraser', 'pambura', 'rubber eraser']::text[], 'RUB-RUB', null, 'residual', 'Use it to the end, then put it in the black bin.', 'Gamitin hanggang maubos, saka ilagay sa itim na basurahan.', '[{"title": "Use it up", "detail": "Small pieces still work."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Gumagana pa ang maliliit."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['pen']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('expired-medicine', 'Medicine / blister pack', 'Gamot', array['medicine', 'pills', 'tablets', 'blister pack', 'gamot', 'expired medicine', 'syrup']::text[], 'MED-DRUG', null, 'hazardous', 'Keep it in its pack. Bring it to a pharmacy or hazardous waste collection point.', 'Iwan sa pakete. Dalhin sa botika o sa koleksyon ng mapanganib na basura.', '[{"title": "Keep it packed", "detail": "Leave pills in their blister or bottle."}, {"title": "Bring it to a drop-off", "detail": "Use a pharmacy take-back or a hazardous waste collection point."}]'::jsonb, '[{"title": "Iwan sa pakete", "detail": "Huwag alisin ang gamot sa blister o bote."}, {"title": "Dalhin sa drop-off", "detail": "Sa take-back ng botika o koleksyon ng mapanganib na basura."}]'::jsonb, 'Do not flush or throw it in regular bins.', 'Huwag i-flush o itapon sa ordinaryong basurahan.', '{}'::text[], '{}'::text[], 'Medicine can poison children or pets, and it pollutes water if flushed or thrown loose.', 'Puwedeng makalason ng bata o alagang hayop ang gamot, at nagpaparumi ito ng tubig kapag na-flush o itinapon nang walang balot.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Medicines can poison water and soil if thrown away or flushed.', 'Puwedeng lumason sa tubig at lupa ang gamot kapag basta itinapon o na-flush.', '{}'::text[], 'expired_medicine', array['S-RA9003-22', 'S-DOH-HCWM4']::text[], 'draft', '{}'::text[], null),
  ('face-mask', 'Face mask', 'Face mask', array['mask', 'surgical mask', 'facemask', 'kn95']::text[], 'MED-PPE', null, 'residual', 'Fold it inward, cut the ear loops, and place it in the black bin.', 'Itupi papaloob, gupitin ang tali sa tainga, at ilagay sa itim na basurahan.', '[{"title": "Fold it inward", "detail": "Keep the used side inside."}, {"title": "Cut the ear loops", "detail": "Loops can trap animals."}, {"title": "Sort it", "detail": "Place it in the black bin."}]'::jsonb, '[{"title": "Itupi papaloob", "detail": "Nasa loob ang gamit na bahagi."}, {"title": "Gupitin ang tali", "detail": "Puwedeng sumabit dito ang mga hayop."}, {"title": "Ilagay", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Used masks may carry germs and are made of mixed materials that can''t be recycled.', 'Puwedeng may mikrobyo ang gamit na mask at gawa ito sa pinaghalong materyales na hindi nare-recycle.', '{}'::text[], 'face_mask', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('floor-tile', 'Floor or wall tile', 'Tiles', array['tile', 'tiles', 'bathroom tile', 'tisa']::text[], 'CER-TILE', null, 'residual', 'A few pieces can be wrapped for the black bin. For renovation waste, ask your barangay.', 'Puwedeng balutin ang ilang piraso para sa itim. Para sa basura ng renovation, itanong sa barangay.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Use leftover tiles for coasters or stepping stones']::text[], array['Gamitin ang sobrang tiles bilang coaster o tapakan']::text[], '{}'::text[], '{}'::text[], null, null, array['construction-rubble']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('flowers', 'Old flowers', 'Lumang bulaklak', array['flowers', 'bouquet', 'bulaklak', 'wreath']::text[], 'ORG-GARDEN', null, 'biodegradable', 'Flowers go in the green bin. Ribbons, plastic wrap and floral foam go in the black bin.', 'Ang bulaklak ay sa berde. Ang laso, plastik at floral foam ay sa itim.', '[{"title": "Unwrap it", "detail": "Remove ribbons, wire and plastic."}, {"title": "Compost the flowers", "detail": "Green bin or compost."}]'::jsonb, '[{"title": "Alisin ang balot", "detail": "Tanggalin ang laso, alambre at plastik."}, {"title": "I-compost ang bulaklak", "detail": "Sa berde o compost."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['leaves', 'grass-clippings']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('fluorescent-tube', 'Fluorescent tube', 'Fluorescent na tubo', array['fluorescent', 'tube light', 'flourescent', 'tubo ng ilaw', 't8']::text[], 'LIG-FLUO', null, 'hazardous', 'Keep it whole, wrap it, and bring it to a lamp take-back or hazardous waste collection.', 'Huwag basagin, balutin, at dalhin sa lamp take-back o koleksyon ng mapanganib na basura.', '[{"title": "Keep it whole", "detail": "Don''t break it."}, {"title": "Wrap it", "detail": "Use its box or thick paper."}, {"title": "Bring it in", "detail": "Lamp take-back or hazardous waste collection."}]'::jsonb, '[{"title": "Huwag basagin", "detail": "Hawakan nang maingat."}, {"title": "Balutin", "detail": "Gamitin ang kahon nito o makapal na papel."}, {"title": "Dalhin", "detail": "Sa lamp take-back o koleksyon ng mapanganib na basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Fluorescent tubes and CFLs contain mercury. A broken lamp releases mercury vapour.', 'May mercury ang fluorescent at CFL. Naglalabas ng singaw ng mercury ang basag na ilaw.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Philippine rules on lamp waste require producers and LGUs to set up collection for mercury-containing lamps.', 'May patakaran sa Pilipinas na nag-aatas sa mga gumagawa at LGU na mangolekta ng ilaw na may mercury.', array['light-bulb', 'broken-fluorescent']::text[], 'light_bulb', array['S-RA9003-22', 'S-RA9003-3PP', 'S-JAO-LAMPS']::text[], 'draft', '{}'::text[], null),
  ('foam-cushion', 'Foam cushion or pillow', 'Foam na unan o kutson-kutsunan', array['foam', 'cushion', 'pillow', 'unan', 'foam pillow']::text[], 'RUB-FOAM', null, 'residual', 'Donate clean cushions. Old foam can stuff pet beds; otherwise, black bin or bulky pickup.', 'I-donate ang malinis na unan. Puwedeng palaman sa higaan ng alaga ang lumang foam; kung hindi, sa itim o bulky.', '[{"title": "Wash the cover", "detail": "Covers can be donated or reused."}, {"title": "Reuse or sort", "detail": "Pet beds, or the black bin."}]'::jsonb, '[{"title": "Labhan ang punda", "detail": "Puwedeng i-donate o gamitin ulit ang punda."}, {"title": "Gamitin o itapon", "detail": "Higaan ng alaga, o sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use old foam to stuff a pet bed']::text[], array['Gawing palaman sa higaan ng alaga']::text[], '{}'::text[], '{}'::text[], null, null, array['mattress']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('foil-tray', 'Aluminum food tray', 'Aluminum na tray ng pagkain', array['foil tray', 'aluminum tray', 'baking tray', 'food tray']::text[], 'MET-FOIL', null, 'recyclable', 'Scrape and rinse it, then flatten it for the blue bin.', 'Kayurin at banlawan, saka pitpitin para sa asul na basurahan.', '[{"title": "Scrape it", "detail": "Leftovers go in the green bin."}, {"title": "Rinse and flatten", "detail": "Clean trays recycle; greasy ones don''t."}]'::jsonb, '[{"title": "Kayurin", "detail": "Ang tira ay sa berdeng basurahan."}, {"title": "Banlawan at pitpitin", "detail": "Nare-recycle ang malinis; hindi ang may mantika."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Wash and reuse it for baking']::text[], array['Hugasan at gamitin ulit sa pagbe-bake']::text[], '{}'::text[], '{}'::text[], null, null, array['aluminum-foil']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('food-scraps', 'Food scraps', 'Tira-tirang pagkain', array['leftovers', 'food waste', 'rice', 'fruit peel', 'tira', 'tirang pagkain', 'kanin', 'mango peel']::text[], 'ORG-FOOD', null, 'biodegradable', 'Scrape food into the green bin. No plastic or packaging.', 'Ilagay ang pagkain sa berdeng basurahan. Walang plastik o balot.', '[{"title": "Separate the packaging", "detail": "Take food out of wrappers and containers."}, {"title": "Scrape it in", "detail": "Put only the food in the green bin."}]'::jsonb, '[{"title": "Ihiwalay ang balot", "detail": "Alisin ang pagkain sa balot at lalagyan."}, {"title": "Ilagay", "detail": "Pagkain lang ang ilagay sa berdeng basurahan."}]'::jsonb, 'Remove any wrapper or container first.', 'Alisin muna ang balot o lalagyan.', '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Food waste can be composted. Mixed with plastic, it can''t.', 'Puwedeng i-compost ang tirang pagkain. Kapag nahaluan ng plastik, hindi na.', '{}'::text[], 'food_scraps', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('fruit-peel', 'Fruit peels and cores', 'Balat at ubod ng prutas', array['balat ng mangga', 'orange peel', 'apple core', 'pineapple skin', 'balat ng prutas']::text[], 'ORG-FOOD', null, 'biodegradable', 'Peels and cores go in the green bin or compost. Remove fruit stickers first.', 'Ang balat at ubod ay sa berdeng basurahan o compost. Tanggalin muna ang sticker.', '[{"title": "Remove stickers", "detail": "Stickers are plastic and go in the black bin."}, {"title": "Compost it", "detail": "Green bin or compost pile."}]'::jsonb, '[{"title": "Tanggalin ang sticker", "detail": "Plastik ang sticker at sa itim ito."}, {"title": "I-compost", "detail": "Sa berdeng basurahan o compost."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Dry citrus peels to freshen rooms']::text[], array['Patuyuin ang balat ng dalandan pampabango ng kuwarto']::text[], '{}'::text[], '{}'::text[], null, null, array['banana-peel', 'vegetable-scraps']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('garden-hose', 'Garden hose', 'Hose', array['hose', 'garden hose', 'water hose', 'medyas ng tubig']::text[], 'RUB-RUB', null, 'residual', 'Patch leaks first. Cut old hoses into short lengths for the black bin.', 'Tapalan muna ang tagas. Putulin ang lumang hose nang maiikli para sa itim.', '[{"title": "Repair it", "detail": "Hose menders are cheap."}, {"title": "Cut it", "detail": "Short pieces fit in the bin."}]'::jsonb, '[{"title": "Ayusin", "detail": "Mura ang pangdugtong ng hose."}, {"title": "Putulin", "detail": "Kasya sa basurahan ang maiikli."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use pieces to protect tool edges or as door stops']::text[], array['Gamitin ang piraso pang-protekta ng talim o pang-ipit ng pinto']::text[], '{}'::text[], '{}'::text[], null, null, array['bicycle-tube']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('glass-bottle', 'Glass bottle', 'Boteng salamin', array['glass', 'bottle', 'jar', 'bote', 'boteng salamin', 'garapon']::text[], 'GLA-CONT', null, 'recyclable', 'Empty it and keep it whole. Place it in the blue bin.', 'Ubusin at huwag basagin. Ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Pour out any liquid left inside."}, {"title": "Keep it whole", "detail": "Place it gently so it does not break."}, {"title": "Sort it", "detail": "Put it in the blue bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Itapon ang natirang laman."}, {"title": "Huwag basagin", "detail": "Ilapag nang dahan-dahan."}, {"title": "Ilagay", "detail": "Sa asul na basurahan."}]'::jsonb, 'Broken glass: wrap it and give it to staff. Do not put it in any bin loose.', 'Basag na salamin: balutin at ibigay sa staff. Huwag ilagay nang walang balot sa basurahan.', '{}'::text[], '{}'::text[], null, null, 'buys', array['Reuse it as a container or vase.']::text[], array['Gamitin ulit bilang lalagyan o plorera.']::text[], '{}'::text[], '{}'::text[], 'Whole glass bottles can be reused or remelted. Broken glass is a danger to waste workers.', 'Puwedeng gamitin ulit o tunawin ang buong bote. Delikado sa mga nangongolekta ang basag na salamin.', '{}'::text[], 'glass_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-T2C']::text[], 'draft', '{}'::text[], null),
  ('glass-jar', 'Glass jar', 'Garapon', array['garapon', 'jam jar', 'peanut butter jar', 'sauce jar', 'bagoong jar']::text[], 'GLA-CONT', null, 'recyclable', 'Rinse it and reuse it. Otherwise, put the whole jar in the blue bin and the lid with metals.', 'Banlawan at gamitin ulit. Kung hindi, ilagay ang buong garapon sa asul at ang takip kasama ng metal.', '[{"title": "Rinse it", "detail": "Remove food so it doesn''t smell."}, {"title": "Separate the lid", "detail": "Metal lids go with metals."}]'::jsonb, '[{"title": "Banlawan", "detail": "Tanggalin ang pagkain para hindi mangamoy."}, {"title": "Ihiwalay ang takip", "detail": "Ang metal na takip ay kasama ng metal."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Store spices, coins or leftovers', 'Use it as a drinking glass or vase']::text[], array['Lagyan ng pampalasa, barya o tirang ulam', 'Gamitin bilang baso o plorera']::text[], '{}'::text[], '{}'::text[], null, null, array['glass-bottle', 'drinking-glass', 'pyrex-dish']::text[], 'glass_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-T2C']::text[], 'draft', '{}'::text[], null),
  ('glass-medicine-bottle', 'Empty glass medicine bottle', 'Walang lamang bote ng gamot (salamin)', array['medicine bottle', 'syrup bottle', 'vial', 'bote ng gamot']::text[], 'GLA-CONT', null, 'recyclable', 'Use up or properly dispose of the medicine first, rinse the empty bottle, then put it in the blue bin.', 'Ubusin o itapon nang tama ang gamot, banlawan ang bote, saka ilagay sa asul.', '[{"title": "Empty it safely", "detail": "Leftover medicine follows the medicine rules."}, {"title": "Rinse it", "detail": "Rinse the empty bottle."}, {"title": "Remove the cap", "detail": "Plastic caps go in the black bin."}]'::jsonb, '[{"title": "Ubusin nang ligtas", "detail": "Ang natirang gamot ay sundin ang patakaran sa gamot."}, {"title": "Banlawan", "detail": "Banlawan ang walang lamang bote."}, {"title": "Tanggalin ang takip", "detail": "Ang plastik na takip ay sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['expired-medicine', 'medicine-syrup']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('grass-clippings', 'Grass and garden trimmings', 'Damo at pinutol na halaman', array['damo', 'grass', 'garden waste', 'twigs', 'sanga', 'pruning']::text[], 'ORG-GARDEN', null, 'biodegradable', 'Compost grass and trimmings, or put them in the green bin. Never burn them.', 'I-compost ang damo at pinutol, o ilagay sa berde. Huwag kailanman sunugin.', '[{"title": "Cut it small", "detail": "Small pieces compost faster."}, {"title": "Compost it", "detail": "Mix with dry leaves."}]'::jsonb, '[{"title": "Putulin nang maliliit", "detail": "Mas mabilis mabulok ang maliit."}, {"title": "I-compost", "detail": "Ihalo sa tuyong dahon."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Open burning of waste, including garden waste, is banned under RA 9003.', 'Bawal ang pagsusunog ng basura sa ilalim ng RA 9003, kasama ang basura mula sa halaman.', array['leaves']::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('hair-tie', 'Hair tie or elastic', 'Ipit o goma sa buhok', array['pantali', 'hair tie', 'scrunchie', 'elastic', 'ipit']::text[], 'RUB-RUB', null, 'residual', 'Keep using hair ties until they snap, then put them in the black bin.', 'Gamitin ang ipit hanggang maputol, saka ilagay sa itim na basurahan.', '[{"title": "Use it up", "detail": "Stretched ones still bundle cables."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Pantali pa rin ng kable ang lumuwag."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use it to bundle cables or bags']::text[], array['Gamiting pantali ng kable o supot']::text[], '{}'::text[], '{}'::text[], null, null, array['rubber-band']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('halogen-bulb', 'Halogen bulb', 'Halogen na bombilya', array['halogen', 'halogen lamp', 'spotlight bulb', 'car headlight bulb']::text[], 'LIG-INC', null, 'residual', 'Halogen bulbs have no mercury. Wrap the bulb in paper and put it in the black bin.', 'Walang mercury ang halogen. Balutin sa papel at ilagay sa itim na basurahan.', '[{"title": "Let it cool", "detail": "Halogen bulbs get very hot."}, {"title": "Wrap it", "detail": "Paper or its old box, then black bin."}]'::jsonb, '[{"title": "Palamigin", "detail": "Napakainit ng halogen."}, {"title": "Balutin", "detail": "Papel o lumang kahon, saka sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Switch to LED bulbs']::text[], array['Lumipat sa LED na bombilya']::text[], null, null, array['incandescent-bulb', 'led-bulb']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('hdpe-shampoo-bottle', 'Shampoo or detergent bottle', 'Bote ng shampoo o sabon', array['shampoo bottle', 'conditioner bottle', 'dishwashing liquid bottle', 'detergent bottle', 'HDPE', 'bote ng shampoo']::text[], 'PLA-2', 2, 'recyclable', 'Empty and rinse it, then sell it to a junk shop or put it in the blue bin.', 'Ubusin at banlawan, saka ibenta sa junk shop o ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Use up or pour out what''s left."}, {"title": "Rinse it", "detail": "A quick rinse removes soap or shampoo."}, {"title": "Check the number", "detail": "Look for #2 in the triangle on the bottom."}]'::jsonb, '[{"title": "Ubusin", "detail": "Gamitin o itapon ang natira."}, {"title": "Banlawan", "detail": "Tinatanggal ng banlaw ang sabon o shampoo."}, {"title": "Tingnan ang numero", "detail": "Hanapin ang #2 sa tatsulok sa ilalim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Use it as a watering can or a scoop']::text[], array['Gamitin bilang pandilig o panalok']::text[], array['Buy refills from refill stores', 'Choose bigger bottles']::text[], array['Bumili ng refill sa refilling store', 'Pumili ng mas malaking bote']::text[], 'Under the EPR Act (RA 11898), large companies must recover the plastic packaging they put on the market.', 'Sa ilalim ng EPR Act (RA 11898), kailangang bawiin ng malalaking kumpanya ang plastik na packaging nila.', array['plastic-bottle', 'cooking-oil-bottle']::text[], 'plastic_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-STD-RIC', 'S-RA11898']::text[], 'draft', '{}'::text[], null),
  ('incandescent-bulb', 'Incandescent or halogen bulb', 'Incandescent o halogen na bombilya', array['incandescent', 'yellow bulb', 'halogen', 'old bulb']::text[], 'LIG-INC', null, 'residual', 'These have no mercury. Wrap the bulb and put it in the black bin.', 'Walang mercury ang mga ito. Balutin ang bombilya at ilagay sa itim na basurahan.', '[{"title": "Wrap it", "detail": "Use paper so it can''t shatter in the bag."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Balutin", "detail": "Gumamit ng papel para hindi mabasag sa supot."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Switch to LED bulbs, which last much longer']::text[], array['Lumipat sa LED, na mas matagal']::text[], null, null, array['led-bulb', 'cfl-bulb']::text[], 'light_bulb', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('ink-cartridge', 'Ink cartridge', 'Ink cartridge', array['printer ink', 'toner', 'cartridge', 'ink']::text[], 'ELE-ACC', null, 'hazardous', 'Bring it to a cartridge take-back or e-waste collection point.', 'Dalhin sa take-back ng cartridge o sa e-waste collection point.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Ink and toner can stain and irritate skin and eyes. Cartridges are e-waste.', 'Puwedeng makamantsa at makairita sa balat at mata ang tinta at toner. E-waste ang cartridge.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Ink and electronics in cartridges are harmful in regular waste.', 'Mapanganib sa ordinaryong basura ang tinta at electronics sa cartridge.', '{}'::text[], null, array['S-RA9003-22', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('insecticide', 'Liquid insecticide', 'Pamatay-insekto (likido)', array['insecticide', 'pesticide', 'mosquito killer', 'pamatay ng ipis']::text[], 'HHW-PEST', null, 'hazardous', 'Keep it in its labelled container and bring leftovers to hazardous waste collection.', 'Iwan sa lalagyang may label at dalhin ang natira sa koleksyon ng mapanganib.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Pesticides are poisonous to people, pets and fish.', 'Nakalalason sa tao, alaga at isda ang pesticide.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['spray-can', 'rat-poison']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('jeans', 'Jeans', 'Pantalong maong', array['maong', 'jeans', 'denim', 'pantalon']::text[], 'TEX-CLOTH', null, 'residual', 'Donate or repair jeans. Old denim makes strong bags and patches.', 'I-donate o ipaayos ang maong. Nagagawang matibay na bag at tagpi ang lumang denim.', '[{"title": "Wash it", "detail": "Donations should be clean."}, {"title": "Donate or repair", "detail": "Patch holes or replace zippers."}]'::jsonb, '[{"title": "Labhan", "detail": "Dapat malinis ang ido-donate."}, {"title": "I-donate o ipaayos", "detail": "Tagpian ang butas o palitan ang zipper."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away', 'Make it into a bag or patches']::text[], array['Kung magagamit pa, ipamigay o i-donate', 'Gawing bag o tagpi']::text[], '{}'::text[], '{}'::text[], null, null, array['t-shirt']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('juice-pouch', 'Drink or food pouch', 'Pouch ng inumin o pagkain', array['juice pouch', 'stand up pouch', 'doypack', 'refill pouch', 'spout pouch']::text[], 'CMP-MIXED', null, 'residual', 'Pouches are layered plastic and foil. Empty and rinse them, then use the black bin.', 'Patong-patong na plastik at foil ang pouch. Ubusin at banlawan, saka ilagay sa itim.', '[{"title": "Empty it", "detail": "Squeeze out what''s left."}, {"title": "Rinse and dry", "detail": "Clean pouches can go to plastic programmes."}]'::jsonb, '[{"title": "Ubusin", "detail": "Pigain ang natira."}, {"title": "Banlawan at patuyuin", "detail": "Puwede sa programa ng plastik ang malinis."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Choose bottles or bulk refills']::text[], array['Pumili ng bote o refill']::text[], null, null, array['plastic-sachet', 'snack-wrapper']::text[], null, array['S-RA9003-22', 'S-QC-T2C', 'S-RA11898']::text[], 'draft', '{}'::text[], null),
  ('kitchen-sponge', 'Kitchen sponge', 'Espongha', array['sponge', 'espongha', 'scrub', 'dish sponge']::text[], 'RUB-FOAM', null, 'residual', 'Worn sponges go in the black bin. Reuse old ones for cleaning floors or shoes first.', 'Ang lumang espongha ay sa itim. Gamitin muna sa paglilinis ng sahig o sapatos.', '[{"title": "Reuse it", "detail": "Clean floors, shoes or tools."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Gamitin ulit", "detail": "Panlinis ng sahig, sapatos o gamit."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Try loofah (patola) sponges, which compost']::text[], array['Subukan ang patola na espongha na nabubulok']::text[], null, null, array['rags']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('lancet', 'Lancet or glucose test strip', 'Lancet o glucose test strip', array['lancet', 'blood sugar strip', 'glucose strip', 'finger prick']::text[], 'MED-SHARP', null, 'hazardous', 'Put lancets in the same sealed hard container as needles. Ask your health centre where to bring it.', 'Ilagay ang lancet sa saradong matigas na lalagyan kasama ng karayom. Itanong sa health center kung saan dadalhin.', '[{"title": "Use a hard container", "detail": "A thick plastic bottle with a screw cap, like a detergent bottle."}, {"title": "Seal and label it", "detail": "Tape the cap and write SHARPS on it."}, {"title": "Ask where to bring it", "detail": "Your barangay health centre or pharmacy."}]'::jsonb, '[{"title": "Gumamit ng matigas na lalagyan", "detail": "Makapal na plastik na bote na may takip, tulad ng bote ng sabon."}, {"title": "Isara at lagyan ng label", "detail": "Lagyan ng tape ang takip at isulat ang SHARPS."}, {"title": "Itanong kung saan dadalhin", "detail": "Sa barangay health center o botika."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Lancets are sharp and carry blood.', 'Matulis ang lancet at may dugo.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['syringe-needle']::text[], null, array['S-RA9003-22', 'S-DOH-HCWM4']::text[], 'draft', '{}'::text[], null),
  ('laptop', 'Laptop or computer', 'Laptop o computer', array['laptop', 'computer', 'pc', 'desktop', 'cpu', 'monitor']::text[], 'ELE-SMALL', null, 'hazardous', 'Wipe your data, then donate, sell for parts, or bring it to an e-waste drop-off.', 'Burahin ang data, saka i-donate, ibenta bilang piyesa, o dalhin sa e-waste drop-off.', '[{"title": "Back up and wipe it", "detail": "Save your files, then reset it to remove personal data."}, {"title": "Remove batteries if easy", "detail": "Tape their ends; they go to battery collection."}, {"title": "Bring it in", "detail": "Donate if it works, or bring it to an e-waste drop-off."}]'::jsonb, '[{"title": "I-back up at burahin", "detail": "I-save ang files, saka i-reset para mabura ang personal na data."}, {"title": "Alisin ang baterya kung madali", "detail": "Takpan ng tape; sa koleksyon ng baterya ito."}, {"title": "Dalhin", "detail": "I-donate kung gumagana, o dalhin sa e-waste drop-off."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['laptop-battery', 'computer-mouse']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('laptop-battery', 'Laptop battery', 'Baterya ng laptop', array['laptop battery', 'notebook battery', 'battery pack']::text[], 'BAT-LI', null, 'hazardous', 'Bring it to an e-waste or battery drop-off. A swollen battery must not be pressed or punctured.', 'Dalhin sa e-waste o battery drop-off. Huwag diinan o butasin ang namagang baterya.', '[{"title": "Don''t puncture it", "detail": "Never crush, bend or open it."}, {"title": "Tape the contacts", "detail": "Cover metal contacts with tape."}, {"title": "Bring it in", "detail": "Battery or e-waste drop-off, never the regular bin."}]'::jsonb, '[{"title": "Huwag butasin", "detail": "Huwag durugin, baluktutin o buksan."}, {"title": "Takpan ng tape", "detail": "Takpan ng tape ang metal na contact."}, {"title": "Dalhin", "detail": "Sa battery o e-waste drop-off, hindi sa ordinaryong basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Lithium-ion batteries can catch fire or explode if crushed, punctured, overheated or swollen.', 'Puwedeng magliyab o sumabog ang lithium-ion na baterya kapag nadurog, nabutas, nainitan o namaga.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['laptop', 'power-bank']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('leaves', 'Leaves', 'Dahon', array['leaf', 'dry leaves', 'dahon', 'twigs', 'grass', 'garden waste']::text[], 'ORG-GARDEN', null, 'biodegradable', 'Place in the green bin or compost.', 'Ilagay sa berdeng basurahan o i-compost.', '[{"title": "Remove litter", "detail": "Pick out any plastic or wrappers mixed in."}, {"title": "Compost or green bin", "detail": "Leaves make good compost."}]'::jsonb, '[{"title": "Alisin ang kalat", "detail": "Tanggalin ang plastik o balot na nahalo."}, {"title": "I-compost", "detail": "Magandang compost ang dahon."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Garden waste breaks down into useful compost.', 'Nagiging kapaki-pakinabang na compost ang basura mula sa halaman.', '{}'::text[], 'leaves', array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('led-bulb', 'LED bulb', 'LED na bombilya', array['led', 'led bulb', 'led light', 'ilaw']::text[], 'LIG-LED', null, 'hazardous', 'LED bulbs have electronics inside. Bring them to an e-waste or lamp drop-off.', 'May electronics sa loob ang LED. Dalhin sa e-waste o lamp drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'LED bulbs contain small electronic parts and metals that don''t belong in household bins.', 'May maliliit na electronics at metal ang LED na hindi dapat sa basurahan sa bahay.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['cfl-bulb', 'led-tube']::text[], 'light_bulb', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('led-tube', 'LED tube light', 'LED na tubo', array['led tube', 't8 led', 'led tube light']::text[], 'LIG-LED', null, 'hazardous', 'Bring old LED tubes to an e-waste or lamp drop-off.', 'Dalhin ang lumang LED na tubo sa e-waste o lamp drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'LED tubes contain electronic drivers and metals that need e-waste handling.', 'May electronics at metal ang LED na tubo na kailangang i-handle bilang e-waste.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['led-bulb', 'fluorescent-tube']::text[], 'light_bulb', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('light-bulb', 'Light bulb', 'Bombilya', array['bulb', 'lamp', 'fluorescent', 'led bulb', 'bombilya', 'ilaw']::text[], 'LIG-FLUO', null, 'hazardous', 'Keep it whole and wrap it. Give it to staff or a collection point.', 'Huwag basagin at balutin. Ibigay sa staff o sa collection point.', '[{"title": "Keep it whole", "detail": "Do not break it."}, {"title": "Wrap it", "detail": "Use paper or its original box."}, {"title": "Hand it over", "detail": "Give it to staff or a hazardous waste collection point."}]'::jsonb, '[{"title": "Huwag basagin", "detail": "Hawakan nang maingat."}, {"title": "Balutin", "detail": "Gamitin ang papel o ang orihinal na kahon."}, {"title": "Ibigay", "detail": "Sa staff o sa koleksyon ng mapanganib na basura."}]'::jsonb, 'Fluorescent bulbs contain mercury. Do not break them.', 'May mercury ang fluorescent na bombilya. Huwag itong basagin.', '{}'::text[], '{}'::text[], 'Fluorescent tubes and CFLs contain mercury. A broken lamp releases mercury vapour.', 'May mercury ang fluorescent at CFL. Naglalabas ng singaw ng mercury ang basag na ilaw.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Fluorescent bulbs contain mercury, which is toxic when released.', 'May mercury ang fluorescent na bombilya, na nakalalason kapag lumabas.', '{}'::text[], 'light_bulb', array['S-RA9003-22', 'S-RA9003-3PP', 'S-JAO-LAMPS']::text[], 'draft', '{}'::text[], null),
  ('liquor-bottle', 'Wine or liquor bottle', 'Bote ng alak', array['wine bottle', 'gin bottle', 'liquor bottle', 'bote ng alak', 'lapad']::text[], 'GLA-CONT', null, 'recyclable', 'Empty it and keep it whole. Sell it to a junk shop or put it in the blue bin.', 'Ubusin at huwag basagin. Ibenta sa junk shop o ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Pour out what''s left."}, {"title": "Remove the cap", "detail": "Caps go with metals or plastics."}]'::jsonb, '[{"title": "Ubusin", "detail": "Itapon ang natira."}, {"title": "Tanggalin ang takip", "detail": "Ang takip ay kasama ng metal o plastik."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Use it as a vase, lamp or water bottle']::text[], array['Gamitin bilang plorera, lampara o lalagyan ng tubig']::text[], '{}'::text[], '{}'::text[], null, null, array['glass-bottle', 'returnable-bottle']::text[], 'glass_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-T2C']::text[], 'draft', '{}'::text[], null),
  ('magazine', 'Magazine or glossy paper', 'Magasin o makintab na papel', array['magazine', 'brochure', 'flyer', 'glossy paper', 'catalog']::text[], 'PAP-CLEAN', null, 'recyclable', 'Keep it dry and put it in the blue bin, or bring it to a junk shop with your other paper.', 'Panatilihing tuyo at ilagay sa asul, o dalhin sa junk shop kasama ng ibang papel.', '[{"title": "Remove plastic", "detail": "Take off plastic covers or freebies."}, {"title": "Keep it dry", "detail": "Stack it with other paper."}]'::jsonb, '[{"title": "Tanggalin ang plastik", "detail": "Alisin ang plastic cover o freebies."}, {"title": "Panatilihing tuyo", "detail": "Isalansan kasama ng ibang papel."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Use pages for gift wrap or crafts']::text[], array['Gamitin ang pahina sa pambalot ng regalo o crafts']::text[], '{}'::text[], '{}'::text[], null, null, array['newspaper', 'paper-sheet']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('mattress', 'Mattress', 'Kutson', array['kutson', 'mattress', 'foam mattress', 'spring bed']::text[], 'BLK-MATT', null, 'residual', 'Donate it if it''s clean and usable. Otherwise, ask your barangay for bulky-waste pickup.', 'I-donate kung malinis at magagamit pa. Kung hindi, itanong sa barangay ang bulky pickup.', '[{"title": "Try to reuse it", "detail": "Donate, sell or repair first."}, {"title": "Ask for pickup", "detail": "Your barangay or city schedules bulky-waste collection."}]'::jsonb, '[{"title": "Subukang gamitin ulit", "detail": "I-donate, ibenta o ipaayos muna."}, {"title": "Magpakuha", "detail": "Ang barangay o lungsod ang nag-iiskedyul ng bulky pickup."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['foam-cushion', 'sofa']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('medicine-syrup', 'Liquid medicine or syrup', 'Gamot na likido o syrup', array['syrup', 'cough syrup', 'liquid medicine', 'antibiotic suspension', 'vitamins']::text[], 'MED-DRUG', null, 'hazardous', 'Keep it in its bottle with the cap on. Ask a pharmacy or health centre about take-back.', 'Iwan sa bote at nakatakip. Itanong sa botika o health center ang take-back.', '[{"title": "Keep it capped", "detail": "Don''t pour it out."}, {"title": "Ask about take-back", "detail": "Pharmacy or barangay health centre."}]'::jsonb, '[{"title": "Panatilihing nakatakip", "detail": "Huwag ibuhos."}, {"title": "Itanong ang take-back", "detail": "Sa botika o barangay health center."}]'::jsonb, null, null, array['Don''t pour it down the sink or toilet']::text[], array['Huwag ibuhos sa lababo o inidoro']::text[], 'Medicine can poison children or pets and pollutes water.', 'Puwedeng makalason ng bata o alaga ang gamot at nagpaparumi ito ng tubig.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['expired-medicine', 'glass-medicine-bottle']::text[], 'expired_medicine', array['S-RA9003-22', 'S-DOH-HCWM4']::text[], 'draft', '{}'::text[], null),
  ('mercury-thermometer', 'Mercury thermometer', 'Thermometer na may mercury', array['thermometer', 'mercury thermometer', 'glass thermometer']::text[], 'HHW-CHEM', null, 'hazardous', 'Don''t break it. Seal it in a jar and bring it to hazardous waste collection.', 'Huwag basagin. Isara sa garapon at dalhin sa koleksyon ng mapanganib na basura.', '[{"title": "Keep it whole", "detail": "Put it in a sealed jar."}, {"title": "If it breaks", "detail": "Air out the room; collect beads with stiff paper, never a vacuum."}, {"title": "Bring it in", "detail": "Hazardous waste collection."}]'::jsonb, '[{"title": "Huwag basagin", "detail": "Ilagay sa saradong garapon."}, {"title": "Kung nabasag", "detail": "Pahanginan; ipunin ang mercury gamit ang matigas na papel, hindi vacuum."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Mercury is toxic; a broken thermometer releases mercury droplets and vapour.', 'Nakalalason ang mercury; naglalabas ng mercury ang basag na thermometer.', null, '{}'::text[], '{}'::text[], array['Use a digital thermometer']::text[], array['Gumamit ng digital na thermometer']::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['fluorescent-tube']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('metal-bottle-cap', 'Metal bottle cap', 'Tansan', array['tansan', 'crown cap', 'bottle cap', 'metal lid', 'takip ng bote']::text[], 'MET-FE', null, 'recyclable', 'Collect caps in a can and put the can in the blue bin. Loose caps get lost in sorting.', 'Ipunin ang tansan sa lata at ilagay ang lata sa asul. Nawawala sa pag-uuri ang maluwag na tansan.', '[{"title": "Collect them", "detail": "Drop caps into an empty can."}, {"title": "Close it", "detail": "Press the can top shut."}]'::jsonb, '[{"title": "Ipunin", "detail": "Ihulog ang tansan sa walang lamang lata."}, {"title": "Isara", "detail": "Pitpitin ang bibig ng lata."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['glass-bottle', 'sardine-can']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('milk-carton', 'Milk or juice carton', 'Karton ng gatas o juice', array['milk carton', 'juice box', 'karton ng gatas', 'drink box']::text[], 'CMP-CARTON', null, 'residual', 'Rinse and flatten it. Put it in the black bin unless your area collects cartons.', 'Banlawan at pitpitin. Ilagay sa itim maliban kung may koleksyon ng karton sa inyo.', '[{"title": "Rinse it", "detail": "Milk smells quickly."}, {"title": "Flatten it", "detail": "Open the top and press it flat."}]'::jsonb, '[{"title": "Banlawan", "detail": "Mabilis mangamoy ang gatas."}, {"title": "Pitpitin", "detail": "Buksan ang itaas at pindutin nang patag."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['tetra-pack']::text[], 'tetra_pack', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('mirror', 'Mirror', 'Salamin (pansalamin)', array['mirror', 'salamin', 'pansalamin', 'broken mirror']::text[], 'GLA-FLAT', null, 'residual', 'Donate a whole mirror. A broken one gets wrapped, labelled BASAG and put in the black bin.', 'I-donate ang buong salamin. Ang basag ay balutin, lagyan ng BASAG at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, 'Mirrors have a metal coating, so they can''t go with glass bottles.', 'May metal na coating ang salamin kaya hindi ito puwede sa bote.', '{}'::text[], '{}'::text[], null, null, 'none', array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['window-glass', 'broken-glass']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('mobile-phone', 'Mobile phone', 'Cellphone', array['cellphone', 'cp', 'phone', 'smartphone', 'selpon', 'tablet']::text[], 'ELE-SMALL', null, 'hazardous', 'Wipe your data, then donate it or bring it to an e-waste drop-off. Never put it in a bin.', 'Burahin ang data, saka i-donate o dalhin sa e-waste drop-off. Huwag ilagay sa basurahan.', '[{"title": "Back up and wipe it", "detail": "Save your files, then reset it to remove personal data."}, {"title": "Remove batteries if easy", "detail": "Tape their ends; they go to battery collection."}, {"title": "Bring it in", "detail": "Donate if it works, or bring it to an e-waste drop-off."}]'::jsonb, '[{"title": "I-back up at burahin", "detail": "I-save ang files, saka i-reset para mabura ang personal na data."}, {"title": "Alisin ang baterya kung madali", "detail": "Takpan ng tape; sa koleksyon ng baterya ito."}, {"title": "Dalhin", "detail": "I-donate kung gumagana, o dalhin sa e-waste drop-off."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['e-waste', 'phone-battery']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('motor-oil', 'Used motor oil', 'Gamit na langis ng makina', array['motor oil', 'engine oil', 'used oil', 'langis']::text[], 'HHW-AUTO', null, 'hazardous', 'Put used oil in a sealed container and bring it to an auto shop or hazardous waste collection.', 'Ilagay ang gamit na langis sa saradong lalagyan at dalhin sa auto shop o koleksyon ng mapanganib.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Used motor oil contains heavy metals; a little can pollute a lot of water.', 'May heavy metals ang gamit na langis; kaunti lang ay nakapagpaparumi ng maraming tubig.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['car-battery']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('muriatic-acid', 'Muriatic acid or toilet cleaner', 'Muriatic acid o panlinis ng inidoro', array['muriatic acid', 'toilet bowl cleaner', 'acid', 'asido']::text[], 'HHW-CHEM', null, 'hazardous', 'Keep it capped and labelled. Bring leftovers to hazardous waste collection.', 'Panatilihing nakatakip at may label. Dalhin ang natira sa koleksyon ng mapanganib.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Strong acids burn skin and eyes and react dangerously with bleach.', 'Nakapapaso sa balat at mata ang matapang na asido at delikado kapag nahalo sa bleach.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['bleach']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('nail-polish', 'Nail polish', 'Cutex', array['nail polish', 'cutex', 'nail paint']::text[], 'HHW-COSM', null, 'hazardous', 'Keep it closed and bring old nail polish to hazardous waste collection.', 'Panatilihing sarado at dalhin ang lumang cutex sa koleksyon ng mapanganib na basura.', '[{"title": "Keep it closed", "detail": "Store it upright, away from heat."}, {"title": "Bring it in", "detail": "Hazardous waste collection."}]'::jsonb, '[{"title": "Panatilihing sarado", "detail": "Itayo, malayo sa init."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Nail polish is flammable and its solvents are toxic.', 'Madaling magliyab ang cutex at nakalalason ang solvent nito.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['acetone']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('newspaper', 'Newspaper', 'Diyaryo', array['diyaryo', 'dyaryo', 'old newspaper', 'broadsheet', 'tabloid']::text[], 'PAP-CLEAN', null, 'recyclable', 'Keep it dry, stack and tie it, then sell it to a junk shop or put it in the blue bin.', 'Panatilihing tuyo, isalansan at itali, saka ibenta sa junk shop o ilagay sa asul.', '[{"title": "Keep it dry", "detail": "Wet paper can''t be recycled."}, {"title": "Stack and tie it", "detail": "Junk shops buy bundled paper by the kilo."}]'::jsonb, '[{"title": "Panatilihing tuyo", "detail": "Hindi nare-recycle ang basang papel."}, {"title": "Isalansan at itali", "detail": "Binibili ng junk shop ang papel kada kilo."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'buys', array['Use it to wrap fragile items', 'Line a compost or pet area']::text[], array['Pambalot ng babasagin', 'Sapin sa compost o lugar ng alaga']::text[], '{}'::text[], '{}'::text[], 'Under RA 9003, recyclables must be free from contamination, so clean and dry items are the ones that get recycled.', 'Ayon sa RA 9003, dapat walang dumi ang recyclable, kaya ang malinis at tuyo ang nare-recycle.', array['paper-sheet', 'magazine']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('nine-volt-battery', '9V battery', '9V na baterya', array['9v battery', 'square battery', 'smoke detector battery']::text[], 'BAT-ALK', null, 'hazardous', 'Tape both terminals: 9V batteries can spark if they touch metal. Bring them to battery collection.', 'Takpan ng tape ang dalawang terminal: kumikislap ang 9V kapag nadikit sa metal. Dalhin sa koleksyon.', '[{"title": "Tape the ends", "detail": "Cover the terminals so they can''t spark."}, {"title": "Keep them dry", "detail": "Store used batteries in a closed container."}, {"title": "Bring them in", "detail": "Red bin or a battery drop-off."}]'::jsonb, '[{"title": "Takpan ng tape ang dulo", "detail": "Takpan ang terminal para walang kislap."}, {"title": "Panatilihing tuyo", "detail": "Itabi ang gamit na baterya sa saradong lalagyan."}, {"title": "Dalhin", "detail": "Sa pulang basurahan o battery drop-off."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'The two terminals sit side by side, so a loose 9V battery can short-circuit and start a fire.', 'Magkatabi ang dalawang terminal kaya puwedeng mag-short at magliyab ang maluwag na 9V.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['aa-battery']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('noodle-cup', 'Instant noodle cup', 'Baso ng instant noodles', array['cup noodles', 'noodle cup', 'instant cup', 'styro cup']::text[], 'CMP-MIXED', null, 'residual', 'Empty and rinse it, then put the cup and lid in the black bin.', 'Ubusin at banlawan, saka ilagay ang baso at takip sa itim na basurahan.', '[{"title": "Empty it", "detail": "Soup and noodles go in the green bin."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ang sabaw at noodles ay sa berde."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['styrofoam', 'paper-cup']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('old-pot', 'Old pot or pan', 'Lumang kaldero o kawali', array['kaldero', 'kawali', 'pan', 'old cookware', 'sauce pan']::text[], 'MET-SCRAP', null, 'recyclable', 'Donate it if it still works. Otherwise, sell it to a junk shop as scrap metal.', 'I-donate kung magagamit pa. Kung hindi, ibenta sa junk shop bilang scrap.', '[{"title": "Check it", "detail": "Is it still usable?"}, {"title": "Remove plastic handles", "detail": "Handles can go in the black bin."}]'::jsonb, '[{"title": "Suriin", "detail": "Magagamit pa ba?"}, {"title": "Tanggalin ang plastik na hawakan", "detail": "Puwedeng sa itim ang hawakan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'buys', array['If it''s still usable, donate it or give it away', 'Use it as a plant pot']::text[], array['Kung magagamit pa, ipamigay o i-donate', 'Gamitin bilang paso']::text[], '{}'::text[], '{}'::text[], null, null, array['scrap-wire']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('paint-can', 'Paint can', 'Lata ng pintura', array['paint', 'pintura', 'thinner', 'solvent']::text[], 'HHW-PAINT', null, 'hazardous', 'Keep it closed. Bring it to a hazardous waste collection point.', 'Takpan nang mahigpit. Dalhin sa koleksyon ng mapanganib na basura.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Leftover paint and thinner are flammable and toxic. Never pour them down a drain.', 'Madaling magliyab at nakalalason ang tirang pintura at thinner. Huwag ibuhos sa kanal.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Leftover paint and solvents are toxic.', 'Nakalalason ang tirang pintura at solvent.', '{}'::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('paint-thinner', 'Paint thinner or solvent', 'Thinner', array['thinner', 'paint thinner', 'solvent', 'lacquer thinner', 'turpentine']::text[], 'HHW-PAINT', null, 'hazardous', 'Keep it closed in its container and bring it to hazardous waste collection.', 'Panatilihing sarado sa lalagyan at dalhin sa koleksyon ng mapanganib na basura.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Thinner is flammable and its fumes are toxic.', 'Madaling magliyab ang thinner at nakalalason ang singaw.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['paint-can', 'rags']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('painted-wood', 'Painted or treated wood', 'Pinturado o ginamot na kahoy', array['painted wood', 'plywood', 'varnished wood', 'lumber scraps', 'tabla']::text[], 'WOO-TREAT', null, 'residual', 'Painted, varnished or treated wood doesn''t compost. Small pieces go in the black bin.', 'Hindi nabubulok nang ligtas ang pinturado o ginamot na kahoy. Ang maliliit ay sa itim.', '[{"title": "Remove nails", "detail": "Nails go to scrap metal."}, {"title": "Sort it", "detail": "Small pieces in the black bin; large ones for bulky pickup."}]'::jsonb, '[{"title": "Tanggalin ang pako", "detail": "Sa scrap na metal ang pako."}, {"title": "Itapon", "detail": "Maliliit sa itim; malalaki sa bulky pickup."}]'::jsonb, null, null, array['Don''t burn it: paint and treatment chemicals become toxic smoke']::text[], array['Huwag sunugin: nagiging nakalalasong usok ang pintura at kemikal']::text[], null, null, null, array['Give usable boards to carpenters or for DIY projects']::text[], array['Ibigay ang magagamit pa sa karpintero o sa DIY']::text[], '{}'::text[], '{}'::text[], null, null, array['sawdust', 'wooden-chair']::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('paper-bag', 'Paper bag', 'Supot na papel', array['paper bag', 'brown bag', 'takeout bag', 'supot', 'supot na papel']::text[], 'PAP-CLEAN', null, 'recyclable', 'Empty it and flatten it, then drop it in the blue bin.', 'Ubusin ang laman at itupi, saka ilagay sa asul na basurahan.', '[{"title": "Check the bag", "detail": "Keep it only if it is clean, dry and intact."}, {"title": "Give it another use", "detail": "Use it for dry storage or your next shopping trip."}, {"title": "Recycle when worn out", "detail": "Empty and flatten it, then use the blue bin."}]'::jsonb, '[{"title": "Suriin ang supot", "detail": "Itago lang kung malinis, tuyo at buo."}, {"title": "Gamitin ulit", "detail": "Para sa tuyong gamit o sa susunod na pamimili."}, {"title": "I-recycle kapag sira na", "detail": "Itupi at ilagay sa asul na basurahan."}]'::jsonb, 'Greasy or food-soaked paper goes in the black bin.', 'Ang papel na may mantika o basa ng pagkain ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, 'accepts', array['Reuse it first. If it is still clean and sturdy, keep it for another trip. Recycle it when it is no longer usable.']::text[], array['Gamitin muna ulit. Kung malinis at matibay pa, itago para sa susunod na lakad. I-recycle kapag hindi na magagamit.']::text[], '{}'::text[], '{}'::text[], 'Reusing extends the life of paper fibers. Clean, dry paper can then be recycled; grease-soaked paper cannot.', 'Napapahaba ng muling paggamit ang buhay ng hibla ng papel. Nare-recycle ang malinis at tuyong papel; hindi ang may mantika.', '{}'::text[], 'paper_bag', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('paper-cup', 'Paper cup', 'Papel na baso', array['coffee cup', 'paper cup', 'hot cup']::text[], 'PAP-COAT', null, 'residual', 'Empty it, then place it in the black bin.', 'Ubusin ang laman, saka ilagay sa itim na basurahan.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], array['Bring your own mug or tumbler']::text[], array['Magdala ng sariling mug o tumbler']::text[], 'Paper cups have a plastic lining, so they can''t be recycled with paper.', 'May plastic lining ang papel na baso kaya hindi ito nare-recycle kasama ng papel.', '{}'::text[], null, array['S-RA9003-22', 'S-QC-SP2876']::text[], 'draft', '{}'::text[], null),
  ('paper-napkin', 'Paper napkin', 'Napkin na papel', array['table napkin', 'serviette', 'paper towel', 'tissue napkin']::text[], 'PAP-TISSUE', null, 'biodegradable', 'Used paper napkins go in the green bin. If they touched chemicals, use the black bin.', 'Ang gamit na napkin ay sa berdeng basurahan. Kung nadikitan ng kemikal, sa itim.', '[{"title": "Check it", "detail": "Food and water are fine for compost."}, {"title": "Sort it", "detail": "Green bin, or black if it has chemicals."}]'::jsonb, '[{"title": "Suriin", "detail": "Puwede sa compost kung pagkain o tubig lang."}, {"title": "Itapon", "detail": "Sa berde, o sa itim kung may kemikal."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Use a cloth napkin or handkerchief']::text[], array['Gumamit ng tela o panyo']::text[], null, null, array['used-tissue']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('paper-sheet', 'Paper', 'Papel', array['paper', 'bond paper', 'notebook paper', 'papel', 'scratch paper', 'printout']::text[], 'PAP-CLEAN', null, 'recyclable', 'Keep it dry and uncrumpled. Place it in the blue bin.', 'Panatilihing tuyo at hindi lukot. Ilagay sa asul na basurahan.', '[{"title": "Use both sides", "detail": "Scratch paper still has a blank side for notes."}, {"title": "Keep it dry and flat", "detail": "Do not crumple or wet it."}, {"title": "Sort it", "detail": "Place it in the blue bin."}]'::jsonb, '[{"title": "Gamitin ang kabilang side", "detail": "Puwede pang sulatan ang likod ng scratch paper."}, {"title": "Panatilihing tuyo", "detail": "Huwag lukutin o basain."}, {"title": "Ilagay", "detail": "Sa asul na basurahan."}]'::jsonb, 'Wet or food-stained paper goes in the black bin.', 'Ang basa o may mantsa ng pagkain na papel ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, 'buys', array['Use the blank side for notes.']::text[], array['Gamitin ang blangkong side para sa notes.']::text[], '{}'::text[], '{}'::text[], 'Clean, flat paper has long fibers that recycle well.', 'Mahahaba ang hibla ng malinis at patag na papel kaya madali itong i-recycle.', '{}'::text[], 'paper_sheet', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('pen', 'Pen', 'Ballpen', array['ballpen', 'ball pen', 'marker', 'highlighter']::text[], 'PLA-7', 7, 'residual', 'Place it in the black bin.', 'Ilagay sa itim na basurahan.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Use refillable pens']::text[], array['Gumamit ng refillable na ballpen']::text[], 'Pens mix plastic, metal and ink, so they aren''t recycled here.', 'Pinaghalong plastik, metal at tinta ang ballpen kaya hindi ito nire-recycle dito.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('phone-battery', 'Phone battery', 'Baterya ng cellphone', array['cellphone battery', 'phone battery', 'li-ion', 'lithium battery']::text[], 'BAT-LI', null, 'hazardous', 'Bring old phone batteries to an e-waste or battery drop-off. Never puncture them.', 'Dalhin ang lumang baterya ng cellphone sa e-waste o battery drop-off. Huwag butasin.', '[{"title": "Don''t puncture it", "detail": "Never crush, bend or open it."}, {"title": "Tape the contacts", "detail": "Cover metal contacts with tape."}, {"title": "Bring it in", "detail": "Battery or e-waste drop-off, never the regular bin."}]'::jsonb, '[{"title": "Huwag butasin", "detail": "Huwag durugin, baluktutin o buksan."}, {"title": "Takpan ng tape", "detail": "Takpan ng tape ang metal na contact."}, {"title": "Dalhin", "detail": "Sa battery o e-waste drop-off, hindi sa ordinaryong basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Lithium-ion batteries can catch fire or explode if crushed, punctured, overheated or swollen.', 'Puwedeng magliyab o sumabog ang lithium-ion na baterya kapag nadurog, nabutas, nainitan o namaga.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['power-bank', 'mobile-phone']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('pizza-box', 'Pizza box', 'Kahon ng pizza', array['pizza box', 'greasy box', 'food box']::text[], 'PAP-SOIL', null, 'residual', 'Tear off the clean top for the blue bin. The greasy part goes in the black bin.', 'Punitin ang malinis na takip para sa asul. Ang may mantikang bahagi ay sa itim.', '[{"title": "Empty it", "detail": "Remove leftovers and the plastic table."}, {"title": "Split it", "detail": "Tear the clean parts from the greasy parts."}, {"title": "Sort it", "detail": "Clean parts in the blue bin; greasy parts in the black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Alisin ang tira at ang plastik na mesa-mesaan."}, {"title": "Hatiin", "detail": "Punitin ang malinis na bahagi mula sa may mantika."}, {"title": "Itapon", "detail": "Malinis sa asul; may mantika sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Under RA 9003, recyclables must be free from contamination, so clean and dry items are the ones that get recycled.', 'Ayon sa RA 9003, dapat walang dumi ang recyclable, kaya ang malinis at tuyo ang nare-recycle.', array['cardboard', 'soiled-food-container']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('plastic-bag', 'Plastic bag', 'Plastic bag', array['sando bag', 'grocery bag', 'supot', 'plastik na supot', 'LDPE bag']::text[], 'PLA-FILM', null, 'residual', 'Reuse it as many times as you can. When it''s torn or dirty, put it in the black bin.', 'Gamitin ulit hangga''t kaya. Kapag punit o marumi na, ilagay sa itim na basurahan.', '[{"title": "Reuse it", "detail": "Use it again for shopping or as a bin liner."}, {"title": "Empty it", "detail": "Make sure nothing is inside."}, {"title": "Sort it", "detail": "Put it in the black bin when it can''t be used."}]'::jsonb, '[{"title": "Gamitin ulit", "detail": "Gamitin sa pamimili o bilang supot ng basurahan."}, {"title": "Ubusin ang laman", "detail": "Siguraduhing walang laman."}, {"title": "Itapon", "detail": "Ilagay sa itim kapag hindi na magagamit."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'none', array['Use it as a bin liner', 'Keep it for wet items']::text[], array['Gamitin bilang supot ng basurahan', 'Pagbalutan ng basang gamit']::text[], array['Bring a reusable bag (eco bag) when you shop']::text[], array['Magdala ng eco bag sa pamimili']::text[], null, null, array['courier-pouch', 'plastic-sachet']::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('plastic-bottle', 'Plastic bottle', 'Plastik na bote', array['bottle', 'water bottle', 'pet bottle', 'softdrinks bottle', 'bote', 'plastik na bote', 'mineral water']::text[], 'PLA-1', 1, 'recyclable', 'Empty it, remove the cap, and flatten it. Drop it in the blue bin.', 'Ubusin, tanggalin ang takip at pitpitin. Ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Pour out any drink left inside."}, {"title": "Remove the cap", "detail": "Caps are a different plastic. Put the cap in the blue bin separately."}, {"title": "Flatten it", "detail": "Squeeze out the air to save space, then use the blue bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Itapon ang natirang inumin."}, {"title": "Tanggalin ang takip", "detail": "Ibang plastik ang takip. Ilagay ito nang hiwalay sa asul na basurahan."}, {"title": "Pitpitin", "detail": "Palabasin ang hangin para makatipid ng lugar."}]'::jsonb, 'If it has leftover drink, empty and rinse it first.', 'Kung may natirang inumin, ubusin at banlawan muna.', array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'buys', array['Refill it for water or use it for plant cuttings.']::text[], array['Gamitin ulit bilang lalagyan ng tubig o taniman ng halaman.']::text[], array['Bring a refillable tumbler', 'Use water refill stations']::text[], array['Magdala ng sariling tumbler', 'Gumamit ng water refill station']::text[], 'PET bottles are widely recycled when they are empty and clean. Leftover liquid spoils other recyclables.', 'Malawak na nire-recycle ang PET na bote kapag walang laman at malinis. Nakasisira ng ibang recyclable ang natirang inumin.', '{}'::text[], 'plastic_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-T2C', 'S-STD-RIC']::text[], 'draft', '{}'::text[], null),
  ('plastic-cup', 'Plastic cup', 'Plastik na baso', array['cup', 'milk tea cup', 'plastic glass', 'baso', 'plastik na baso', 'milktea']::text[], 'PLA-5', 5, 'recyclable', 'Empty and rinse it, then drop it in the blue bin.', 'Ubusin at banlawan, saka ilagay sa asul na basurahan.', '[{"title": "Empty it", "detail": "Finish or pour out the drink and remove the straw."}, {"title": "Rinse it", "detail": "A quick rinse removes milk tea or juice residue."}, {"title": "Sort it", "detail": "Drop the clean cup in the blue bin. The straw goes in the black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ubusin ang inumin at alisin ang straw."}, {"title": "Banlawan", "detail": "Tinatanggal ng banlaw ang tira ng milk tea o juice."}, {"title": "Ilagay", "detail": "Malinis na baso sa asul; ang straw ay sa itim."}]'::jsonb, 'If it has milk tea residue or food, rinse it or use the black bin.', 'Kung may tira ng milk tea o pagkain, banlawan o ilagay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, 'none', array['Reuse it as a pen holder or seedling pot.']::text[], array['Gamitin ulit bilang lalagyan ng ballpen o punlaan.']::text[], array['Bring your own tumbler for drinks']::text[], array['Magdala ng sariling tumbler']::text[], 'Clean PP and PET cups are accepted by junk shops. Sticky residue makes them unrecyclable.', 'Tinatanggap ng junk shop ang malinis na PP at PET na baso. Hindi na nare-recycle kapag malagkit.', '{}'::text[], 'plastic_cup', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-SP2876']::text[], 'draft', '{}'::text[], null),
  ('plastic-sachet', 'Plastic sachet', 'Sachet', array['sachet', 'shampoo sachet', 'coffee sachet', '3in1', 'ketchup packet']::text[], 'PLA-FLEX', null, 'residual', 'Empty it, then place it in the black bin.', 'Ubusin ang laman, saka ilagay sa itim na basurahan.', '[]'::jsonb, '[]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'none', '{}'::text[], '{}'::text[], array['Buy bigger packs or refills when you can']::text[], array['Bumili ng mas malaking pakete o refill kung kaya']::text[], 'Sachets are multi-layer plastic and are not recycled here.', 'Multi-layer na plastik ang sachet at hindi ito nire-recycle dito.', '{}'::text[], null, array['S-RA9003-22', 'S-QC-T2C', 'S-RA11898']::text[], 'draft', '{}'::text[], null),
  ('plastic-utensil', 'Plastic utensil', 'Plastik na kubyertos', array['spoon', 'fork', 'plastic spoon', 'plastic fork', 'kutsara', 'tinidor', 'kubyertos']::text[], 'PLA-6', 6, 'residual', 'Place it in the black bin.', 'Ilagay sa itim na basurahan.', '[{"title": "Reuse if you can", "detail": "Wash it and keep it for another meal."}, {"title": "Sort it", "detail": "When worn out, place it in the black bin."}]'::jsonb, '[{"title": "Gamitin ulit kung kaya", "detail": "Hugasan at itago para sa susunod na kain."}, {"title": "Itapon", "detail": "Kapag sira na, ilagay sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Wash and reuse it if it is still intact.']::text[], array['Hugasan at gamitin ulit kung buo pa.']::text[], array['Bring your own spoon and fork']::text[], array['Magdala ng sariling kutsara at tinidor']::text[], 'Small single-use plastics are too small and mixed to recycle here.', 'Masyadong maliit at halo-halo ang maliliit na single-use na plastik para i-recycle dito.', '{}'::text[], 'plastic_utensil', array['S-RA9003-22', 'S-QC-SP2876']::text[], 'draft', '{}'::text[], null),
  ('plywood', 'Plywood or particle board', 'Plywood', array['plywood', 'particle board', 'mdf', 'lawanit', 'chipboard']::text[], 'WOO-TREAT', null, 'residual', 'Reuse or give away usable boards. Glued board isn''t compost; small pieces go in the black bin.', 'Gamitin ulit o ipamigay ang magagamit pa. Hindi compost ang may pandikit; maliliit ay sa itim.', '[{"title": "Offer it first", "detail": "Carpenters and neighbours often want boards."}, {"title": "Cut it down", "detail": "Small pieces in the black bin; big ones to bulky pickup."}]'::jsonb, '[{"title": "Ialok muna", "detail": "Madalas kailangan ng karpintero at kapitbahay."}, {"title": "Hatiin", "detail": "Maliliit sa itim; malalaki sa bulky pickup."}]'::jsonb, null, null, array['Don''t burn it; the glue releases toxic smoke']::text[], array['Huwag sunugin; nakalalason ang usok ng pandikit']::text[], null, null, null, array['Use offcuts for shelves or plant stands']::text[], array['Gamitin ang tira sa istante o patungan ng halaman']::text[], '{}'::text[], '{}'::text[], null, null, array['painted-wood', 'cabinet']::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('popsicle-stick', 'Popsicle stick or toothpick', 'Stick ng ice candy o toothpick', array['popsicle stick', 'ice cream stick', 'toothpick', 'palito']::text[], 'WOO-RAW', null, 'biodegradable', 'Plain wooden sticks and toothpicks go in the green bin.', 'Ang simpleng kahoy na stick at palito ay sa berdeng basurahan.', '[{"title": "Wipe it", "detail": "Remove food."}, {"title": "Sort it", "detail": "Green bin."}]'::jsonb, '[{"title": "Punasan", "detail": "Alisin ang pagkain."}, {"title": "Itapon", "detail": "Sa berdeng basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use sticks for crafts or plant labels']::text[], array['Gamitin sa crafts o label ng halaman']::text[], '{}'::text[], '{}'::text[], null, null, array['bamboo-skewer', 'wooden-chopsticks']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('porcelain-bowl', 'Porcelain bowl', 'Mangkok (porselana)', array['bowl', 'mangkok', 'porcelain', 'soup bowl']::text[], 'CER-DISH', null, 'residual', 'Donate whole bowls. Wrap broken ones, label BASAG and put them in the black bin.', 'I-donate ang buong mangkok. Balutin ang basag, lagyan ng BASAG at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['ceramic-plate']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('power-bank', 'Power bank', 'Power bank', array['power bank', 'powerbank', 'portable charger']::text[], 'BAT-LI', null, 'hazardous', 'Never put a power bank in a bin. Bring it to an e-waste or battery drop-off.', 'Huwag ilagay sa basurahan ang power bank. Dalhin sa e-waste o battery drop-off.', '[{"title": "Don''t puncture it", "detail": "Never crush, bend or open it."}, {"title": "Tape the contacts", "detail": "Cover metal contacts with tape."}, {"title": "Bring it in", "detail": "Battery or e-waste drop-off, never the regular bin."}]'::jsonb, '[{"title": "Huwag butasin", "detail": "Huwag durugin, baluktutin o buksan."}, {"title": "Takpan ng tape", "detail": "Takpan ng tape ang metal na contact."}, {"title": "Dalhin", "detail": "Sa battery o e-waste drop-off, hindi sa ordinaryong basurahan."}]'::jsonb, 'A swollen power bank is dangerous: keep it outside, away from anything flammable, until drop-off.', 'Delikado ang namagang power bank: ilabas, ilayo sa madaling magliyab, hanggang maidala.', '{}'::text[], '{}'::text[], 'Lithium-ion batteries can catch fire or explode if crushed, punctured, overheated or swollen.', 'Puwedeng magliyab o sumabog ang lithium-ion na baterya kapag nadurog, nabutas, nainitan o namaga.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['phone-battery', 'mobile-phone']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('pp-food-tub', 'Plastic food tub', 'Plastik na lalagyan ng pagkain', array['ice cream tub', 'take-out container', 'microwavable container', 'tupperware', 'lalagyan', 'PP container']::text[], 'PLA-5', 5, 'recyclable', 'Wash it and reuse it. When it''s worn out, put the clean tub in the blue bin.', 'Hugasan at gamitin ulit. Kapag luma na, ilagay ang malinis na lalagyan sa asul na basurahan.', '[{"title": "Empty and wash it", "detail": "Scrape food into the green bin, then wash."}, {"title": "Reuse it", "detail": "Use it for leftovers, storage or baon."}, {"title": "Recycle when worn", "detail": "Put the clean tub and lid in the blue bin."}]'::jsonb, '[{"title": "Ubusin at hugasan", "detail": "Ilagay ang tira sa berdeng basurahan, saka hugasan."}, {"title": "Gamitin ulit", "detail": "Para sa tirang ulam, gamit o baon."}, {"title": "I-recycle kapag luma", "detail": "Ilagay ang malinis na lalagyan at takip sa asul."}]'::jsonb, 'Greasy tubs that won''t come clean go in the black bin.', 'Ang may mantikang hindi na malinis ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, 'accepts', array['Use it for leftovers or baon', 'Keep small items in it']::text[], array['Gamitin sa tirang ulam o baon', 'Lagyan ng maliliit na gamit']::text[], array['Bring your own container for take-out']::text[], array['Magdala ng sariling lalagyan sa take-out']::text[], null, null, array['styrofoam', 'soiled-food-container']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z', 'S-STD-RIC']::text[], 'draft', '{}'::text[], null),
  ('printer', 'Printer', 'Printer', array['printer', 'scanner', 'fax machine']::text[], 'ELE-LARGE', null, 'hazardous', 'Remove ink cartridges for take-back, then bring the printer to an e-waste drop-off.', 'Alisin ang cartridge para sa take-back, saka dalhin ang printer sa e-waste drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['ink-cartridge']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('ps-yogurt-drink-bottle', 'Small yogurt drink bottle', 'Maliit na bote ng yogurt drink', array['yogurt drink bottle', 'cultured milk bottle', 'maliit na bote', '#6 PS']::text[], 'PLA-6', 6, 'residual', 'Rinse it, then put it in the black bin. Small #6 bottles are rarely accepted for recycling.', 'Banlawan, saka ilagay sa itim na basurahan. Bihirang tanggapin ang maliit na #6 na bote.', '[{"title": "Rinse it", "detail": "Milk residue smells and attracts ants."}, {"title": "Sort it", "detail": "Put it in the black bin."}]'::jsonb, '[{"title": "Banlawan", "detail": "Mabaho at nilalanggam ang tirang gatas."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Use it as a small seedling pot']::text[], array['Gamitin bilang maliit na punlaan']::text[], '{}'::text[], '{}'::text[], null, null, array['plastic-cup', 'styrofoam']::text[], null, array['S-RA9003-22', 'S-STD-RIC']::text[], 'draft', '{}'::text[], null),
  ('pvc-pipe', 'PVC pipe offcut', 'Putol ng PVC pipe', array['pvc pipe', 'tubo', 'plastic pipe', 'pipe scrap']::text[], 'PLA-3', 3, 'residual', 'Small pieces go in the black bin. Ask your barangay about larger construction scraps.', 'Ang maliliit na putol ay sa itim na basurahan. Itanong sa barangay ang malalaking tira ng konstruksyon.', '[{"title": "Clean it", "detail": "Remove cement or glue if you can."}, {"title": "Sort it", "detail": "Small pieces in the black bin; bulk with construction debris."}]'::jsonb, '[{"title": "Linisin", "detail": "Tanggalin ang semento o pandikit kung kaya."}, {"title": "Itapon", "detail": "Maliliit sa itim; marami ay kasama ng debris ng konstruksyon."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Burning PVC releases harmful smoke, and open burning of waste is banned under RA 9003.', 'Naglalabas ng mapanganib na usok ang sinunog na PVC, at bawal ang pagsusunog ng basura sa ilalim ng RA 9003.', array['construction-rubble']::text[], null, array['S-RA9003-22', 'S-RA9003-48', 'S-STD-RIC']::text[], 'draft', '{}'::text[], null),
  ('pyrex-dish', 'Heat-resistant glass dish', 'Pyrex na pinggan', array['pyrex', 'baking dish', 'oven glass', 'glass bowl']::text[], 'GLA-HEAT', null, 'residual', 'Heat-resistant glass can''t be recycled with bottles. Wrap broken pieces and put them in the black bin.', 'Hindi nare-recycle kasama ng bote ang pyrex. Balutin ang basag at ilagay sa itim.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['drinking-glass', 'glass-jar']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('rags', 'Dirty rags', 'Maruming basahan', array['basahan', 'rag', 'dirty cloth', 'oily rag']::text[], 'TEX-HOME', null, 'residual', 'Put dirty rags in the black bin. Rags with paint, oil or solvent go to hazardous waste collection.', 'Ang maruming basahan ay sa itim. Ang may pintura, langis o solvent ay sa koleksyon ng mapanganib na basura.', '[{"title": "Check it", "detail": "Did it touch paint, thinner or oil?"}, {"title": "Sort it", "detail": "Black bin; chemical rags go to hazardous collection."}]'::jsonb, '[{"title": "Suriin", "detail": "Nadikitan ba ng pintura, thinner o langis?"}, {"title": "Itapon", "detail": "Sa itim; ang may kemikal ay sa koleksyon ng mapanganib."}]'::jsonb, 'Rags soaked in oil or solvent can catch fire on their own; keep them in a closed metal can.', 'Puwedeng kusang magliyab ang basahang babad sa langis o solvent; ilagay sa saradong lata.', '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['t-shirt', 'paint-thinner']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('rat-poison', 'Rat poison', 'Lason sa daga', array['rat poison', 'rodenticide', 'lason sa daga', 'racumin']::text[], 'HHW-PEST', null, 'hazardous', 'Keep it sealed and away from children and pets. Bring leftovers to hazardous waste collection.', 'Panatilihing selyado at malayo sa bata at alaga. Dalhin ang natira sa koleksyon ng mapanganib.', '[{"title": "Keep it in its container", "detail": "Leave it in the original, labelled container."}, {"title": "Close it tightly", "detail": "Tape the cap if it leaks."}, {"title": "Bring it in", "detail": "Hazardous waste collection, never the drain or regular bin."}]'::jsonb, '[{"title": "Iwan sa lalagyan", "detail": "Iwan sa orihinal na lalagyang may label."}, {"title": "Isara nang mahigpit", "detail": "Lagyan ng tape ang takip kung tumutulo."}, {"title": "Dalhin", "detail": "Sa koleksyon ng mapanganib na basura, hindi sa kanal o basurahan."}]'::jsonb, null, null, array['Don''t pour it down the drain', 'Don''t mix it with other chemicals']::text[], array['Huwag ibuhos sa kanal', 'Huwag ihalo sa ibang kemikal']::text[], 'Rat poison can kill pets and harm children who touch or swallow it.', 'Puwedeng makamatay ng alaga at makasakit ng bata ang lason sa daga.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 treats household hazardous wastes like paints and thinners as special wastes that must be kept apart.', 'Itinuturing ng RA 9003 na special waste ang mapanganib na basura sa bahay tulad ng pintura at thinner.', array['insecticide']::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('receipt', 'Receipt (thermal paper)', 'Resibo (thermal na papel)', array['resibo', 'receipt', 'thermal paper', 'atm slip', 'cash register receipt']::text[], 'PAP-THERM', null, 'residual', 'Shiny receipts are thermal paper. Put them in the black bin, not with paper.', 'Thermal na papel ang makintab na resibo. Ilagay sa itim na basurahan, hindi kasama ng papel.', '[{"title": "Check it", "detail": "Thermal paper is shiny and turns dark when scratched."}, {"title": "Sort it", "detail": "Put it in the black bin."}]'::jsonb, '[{"title": "Suriin", "detail": "Makintab ang thermal paper at umiitim kapag kinaskas."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], array['Say no to a printed receipt when you don''t need one']::text[], array['Tanggihan ang naka-print na resibo kung hindi kailangan']::text[], null, null, array['paper-sheet']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('rechargeable-battery', 'Rechargeable AA/AAA battery', 'Rechargeable na baterya', array['rechargeable battery', 'nimh', 'eneloop', 'rechargeable aa']::text[], 'BAT-ALK', null, 'hazardous', 'When it no longer holds a charge, tape the ends and bring it to battery collection.', 'Kapag hindi na nagtatagal ang charge, takpan ng tape at dalhin sa koleksyon ng baterya.', '[{"title": "Tape the ends", "detail": "Cover the terminals so they can''t spark."}, {"title": "Keep them dry", "detail": "Store used batteries in a closed container."}, {"title": "Bring them in", "detail": "Red bin or a battery drop-off."}]'::jsonb, '[{"title": "Takpan ng tape ang dulo", "detail": "Takpan ang terminal para walang kislap."}, {"title": "Panatilihing tuyo", "detail": "Itabi ang gamit na baterya sa saradong lalagyan."}, {"title": "Dalhin", "detail": "Sa pulang basurahan o battery drop-off."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Rechargeables contain metals that are harmful if they leak into soil or water.', 'May mga metal ang rechargeable na nakasasama kapag tumagas sa lupa o tubig.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['aa-battery']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('refrigerator', 'Refrigerator or freezer', 'Refrigerator o freezer', array['ref', 'refrigerator', 'fridge', 'freezer', 'pridyider']::text[], 'BLK-APPL', null, 'hazardous', 'Ask the store about appliance take-back, or use an e-waste collector. Don''t cut the cooling pipes.', 'Itanong sa tindahan ang take-back ng appliance, o gumamit ng e-waste collector. Huwag putulin ang tubo ng pampalamig.', '[{"title": "Empty and clean it", "detail": "Remove food and shelves."}, {"title": "Keep it intact", "detail": "Don''t cut pipes or remove the compressor."}, {"title": "Arrange pickup", "detail": "Store take-back or e-waste collector."}]'::jsonb, '[{"title": "Ubusin at linisin", "detail": "Alisin ang pagkain at istante."}, {"title": "Huwag baklasin", "detail": "Huwag putulin ang tubo o alisin ang compressor."}, {"title": "Magpakuha", "detail": "Take-back ng tindahan o e-waste collector."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Appliances contain electronics, metals and, in cooling appliances, refrigerant gases that must not be released.', 'May electronics at metal ang appliance, at may refrigerant gas ang pampalamig na hindi dapat pakawalan.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['aircon', 'washing-machine']::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('remote-control', 'Remote control', 'Remote control', array['remote', 'tv remote', 'aircon remote']::text[], 'ELE-SMALL', null, 'hazardous', 'Remove the batteries for battery collection, then bring the remote to an e-waste drop-off.', 'Alisin ang baterya para sa koleksyon, saka dalhin ang remote sa e-waste drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['aa-battery']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('returnable-bottle', 'Returnable soft-drink bottle', 'Boteng ibinabalik (softdrinks)', array['returnable bottle', 'bote ng softdrinks', 'deposit bottle', 'bote ng beer', 'litro']::text[], 'GLA-CONT', null, 'recyclable', 'Return it to the store for your deposit. These bottles are refilled, not crushed.', 'Ibalik sa tindahan para sa deposito. Nire-refill ang mga boteng ito, hindi dinudurog.', '[{"title": "Keep it whole", "detail": "Chipped bottles can''t be refilled."}, {"title": "Return it", "detail": "Bring it back to the sari-sari store."}]'::jsonb, '[{"title": "Huwag basagin", "detail": "Hindi na nire-refill ang bote na may tapyas."}, {"title": "Ibalik", "detail": "Dalhin pabalik sa sari-sari store."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'buys', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['glass-bottle']::text[], 'glass_bottle', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('rice-cooker', 'Rice cooker or small appliance', 'Rice cooker o maliit na appliance', array['rice cooker', 'kettle', 'flat iron', 'plantsa', 'blender', 'toaster', 'hair dryer']::text[], 'ELE-LARGE', null, 'hazardous', 'Try a repair shop first. Otherwise, bring it to an e-waste collector.', 'Subukan muna sa repair shop. Kung hindi, dalhin sa e-waste collector.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', 'May lead, mercury at iba pang nakalalasong bahagi ang electronics, at marami ang may baterya sa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['electric-fan']::text[], 'e_waste', array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('rubber-band', 'Rubber band', 'Goma', array['rubber', 'goma', 'rubber band', 'lastiko']::text[], 'RUB-RUB', null, 'residual', 'Reuse it, or place it in the black bin.', 'Gamitin ulit, o ilagay sa itim na basurahan.', '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Keep it for bundling things.']::text[], array['Itago para pantali.']::text[], '{}'::text[], '{}'::text[], 'Small rubber items are not recycled here.', 'Hindi nire-recycle dito ang maliliit na gamit na goma.', '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('rubber-gloves', 'Household rubber gloves', 'Rubber gloves', array['rubber gloves', 'dishwashing gloves', 'cleaning gloves']::text[], 'RUB-RUB', null, 'residual', 'Worn-out rubber gloves go in the black bin. Cut them into bands first if you like.', 'Ang lumang rubber gloves ay sa itim. Puwedeng gupitin muna bilang goma.', '[{"title": "Rinse them", "detail": "Rinse off chemicals."}, {"title": "Sort them", "detail": "Black bin."}]'::jsonb, '[{"title": "Banlawan", "detail": "Banlawan ang kemikal."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Cut the cuffs into rubber bands']::text[], array['Gupitin ang dulo para maging goma']::text[], '{}'::text[], '{}'::text[], null, null, array['disposable-gloves']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('rubber-slippers', 'Rubber slippers', 'Tsinelas', array['tsinelas', 'flip flops', 'slippers', 'sandals']::text[], 'TEX-SHOE', null, 'residual', 'Fix a broken strap first. Worn-out slippers go in the black bin.', 'Ayusin muna ang naputol na strap. Ang lumang tsinelas ay sa itim na basurahan.', '[{"title": "Repair it", "detail": "Replacement straps are cheap at the market."}, {"title": "Sort it", "detail": "Black bin when worn out."}]'::jsonb, '[{"title": "Ayusin", "detail": "Mura ang pamalit na strap sa palengke."}, {"title": "Itapon", "detail": "Sa itim kapag luma na."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['sneakers']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('sanitary-napkin', 'Sanitary napkin', 'Napkin', array['pad', 'sanitary pad', 'napkin', 'feminine napkin', 'panty liner']::text[], 'MED-SAN', null, 'residual', 'Wrap it in paper, then place it in the black bin.', 'Balutin sa papel, saka ilagay sa itim na basurahan.', '[{"title": "Wrap it", "detail": "Wrap it in paper or its wrapper."}, {"title": "Sort it", "detail": "Place it in the black bin."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa papel o sa balot nito."}, {"title": "Ilagay", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Sanitary waste is a health risk and must not be recycled or composted.', 'Panganib sa kalusugan ang sanitary waste kaya hindi ito nire-recycle o kino-compost.', '{}'::text[], 'sanitary_napkin', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('sardine-can', 'Food can (sardines, corned beef)', 'Lata ng sardinas o corned beef', array['sardinas', 'corned beef can', 'tin can', 'canned goods', 'lata ng de-lata']::text[], 'MET-FE', null, 'recyclable', 'Rinse it, press the lid inside, then sell it to a junk shop or put it in the blue bin.', 'Banlawan, ipasok ang takip sa loob, saka ibenta sa junk shop o ilagay sa asul.', '[{"title": "Rinse it", "detail": "Remove sauce and oil."}, {"title": "Mind the lid", "detail": "Push the sharp lid inside the can."}]'::jsonb, '[{"title": "Banlawan", "detail": "Tanggalin ang sarsa at mantika."}, {"title": "Ingatan ang takip", "detail": "Ipasok ang matalim na takip sa loob ng lata."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'buys', array['Use it as a pen holder or small plant pot']::text[], array['Gamitin bilang lalagyan ng ballpen o maliit na paso']::text[], '{}'::text[], '{}'::text[], null, null, array['aluminum-can', 'condensed-milk-can']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('sawdust', 'Sawdust', 'Kusot', array['kusot', 'sawdust', 'wood shavings']::text[], 'WOO-RAW', null, 'biodegradable', 'Sawdust from untreated wood is great for compost. From painted or treated wood, use the black bin.', 'Mabuti sa compost ang kusot mula sa hilaw na kahoy. Mula sa pinturado, sa itim ito.', '[{"title": "Check the wood", "detail": "Untreated or painted?"}, {"title": "Bag it", "detail": "Keep it from blowing around."}]'::jsonb, '[{"title": "Suriin ang kahoy", "detail": "Hilaw o pinturado?"}, {"title": "Isupot", "detail": "Para hindi lumipad."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use it in compost or as a litter box filler']::text[], array['Gamitin sa compost o sa litter box']::text[], '{}'::text[], '{}'::text[], null, null, array['painted-wood']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('school-bag', 'Bag or backpack', 'Bag o backpack', array['bag', 'backpack', 'school bag', 'handbag', 'bag pang-eskwela']::text[], 'TEX-BAG', null, 'residual', 'Replace a broken zipper or strap. Donate usable bags; the black bin is last.', 'Palitan ang sirang zipper o strap. I-donate ang magagamit pa; ang itim ang huli.', '[{"title": "Empty it", "detail": "Check all pockets."}, {"title": "Repair or donate", "detail": "Tailors replace zippers cheaply."}]'::jsonb, '[{"title": "Ubusin ang laman", "detail": "Tingnan ang lahat ng bulsa."}, {"title": "Ipaayos o i-donate", "detail": "Mura magpapalit ng zipper sa mananahi."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['sneakers']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('scrap-wire', 'Scrap wire and metal', 'Scrap na alambre at metal', array['alambre', 'scrap metal', 'copper wire', 'bakal', 'yero', 'kalawang na bakal']::text[], 'MET-SCRAP', null, 'recyclable', 'Junk shops buy scrap metal and copper wire. Bundle it and bring it in.', 'Binibili ng junk shop ang scrap na metal at tansong alambre. Itali at dalhin.', '[{"title": "Bundle it", "detail": "Tie wires and small pieces together."}, {"title": "Mind sharp edges", "detail": "Wrap sharp ends with tape."}]'::jsonb, '[{"title": "Itali", "detail": "Pagsamahin ang alambre at maliliit na piraso."}, {"title": "Ingatan ang talim", "detail": "Takpan ng tape ang matatalim na dulo."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'buys', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Open burning of waste, including burning wires to get the copper, is banned under RA 9003.', 'Bawal sa RA 9003 ang pagsusunog ng basura, kasama ang pagsusunog ng kable para makuha ang tanso.', array['old-pot']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('shredded-paper', 'Shredded paper', 'Ginutay na papel', array['shredded paper', 'paper strips', 'ginupit na papel']::text[], 'PAP-CLEAN', null, 'recyclable', 'Bag shredded paper so it doesn''t scatter, or add it to compost.', 'Isupot ang ginutay na papel para hindi kumalat, o idagdag sa compost.', '[{"title": "Bag it", "detail": "Put it in a paper bag so the strips stay together."}, {"title": "Sort it", "detail": "Blue bin, or mix into compost."}]'::jsonb, '[{"title": "Isupot", "detail": "Ilagay sa supot na papel para magkakasama."}, {"title": "Itapon", "detail": "Sa asul, o ihalo sa compost."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use it as packing filler']::text[], array['Gamitin bilang palaman sa pakete']::text[], '{}'::text[], '{}'::text[], null, null, array['paper-sheet']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('snack-wrapper', 'Snack wrapper', 'Balot ng chichirya', array['chips bag', 'candy wrapper', 'junk food', 'chichirya', 'balot', 'sitsirya', 'biscuit wrapper']::text[], 'PLA-FLEX', null, 'residual', 'Empty any food, then place it in the black bin.', 'Alisin ang natirang pagkain, saka ilagay sa itim na basurahan.', '[{"title": "Empty it", "detail": "Shake out crumbs into the green bin."}, {"title": "Sort it", "detail": "Place the wrapper in the black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ipagpag ang mumo sa berdeng basurahan."}, {"title": "Ilagay", "detail": "Ang balot ay sa itim na basurahan."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'none', '{}'::text[], '{}'::text[], array['Choose snacks in bigger packs or bulk']::text[], array['Pumili ng chichirya sa malaking pakete o bulk']::text[], 'Mixed-layer film is not recyclable here.', 'Hindi nare-recycle dito ang balot na may halo-halong layer.', '{}'::text[], 'snack_wrapper', array['S-RA9003-22', 'S-QC-T2C', 'S-RA11898']::text[], 'draft', '{}'::text[], null),
  ('sneakers', 'Shoes', 'Sapatos', array['sapatos', 'sneakers', 'rubber shoes', 'school shoes', 'leather shoes']::text[], 'TEX-SHOE', null, 'residual', 'A shoe repair shop can fix soles and stitching. Donate wearable pairs; the black bin is last.', 'Naaayos ng sapatero ang swelas at tahi. I-donate ang magagamit pa; ang itim ang huli.', '[{"title": "Repair it", "detail": "Bring it to a sapatero."}, {"title": "Donate it", "detail": "Tie pairs together."}]'::jsonb, '[{"title": "Ipaayos", "detail": "Dalhin sa sapatero."}, {"title": "I-donate", "detail": "Itali nang magkapares."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['rubber-slippers']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('socks', 'Socks', 'Medyas', array['medyas', 'socks', 'stockings']::text[], 'TEX-CLOTH', null, 'residual', 'Mend small holes. Worn-out socks can be dusters, then go in the black bin.', 'Tahiin ang maliliit na butas. Gawing pamunas ang luma, saka ilagay sa itim.', '[{"title": "Mend it", "detail": "Darn small holes."}, {"title": "Reuse it", "detail": "Use it as a duster or shoe cover."}, {"title": "Sort it", "detail": "Black bin when used up."}]'::jsonb, '[{"title": "Tahiin", "detail": "Tahiin ang maliliit na butas."}, {"title": "Gamitin ulit", "detail": "Gawing pamunas o balot ng sapatos."}, {"title": "Itapon", "detail": "Sa itim kapag gamit na gamit na."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use it as a duster']::text[], array['Gawing pamunas']::text[], '{}'::text[], '{}'::text[], null, null, array['t-shirt', 'rags']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('sofa', 'Sofa', 'Sofa', array['sofa', 'couch', 'sopa', 'upuan na malaki']::text[], 'BLK-FURN', null, 'residual', 'Reupholster, sell or donate it. For broken sofas, ask your barangay for bulky pickup.', 'Ipa-reupholster, ibenta o i-donate. Para sa sira, itanong sa barangay ang bulky pickup.', '[{"title": "Try to reuse it", "detail": "Donate, sell or repair first."}, {"title": "Ask for pickup", "detail": "Your barangay or city schedules bulky-waste collection."}]'::jsonb, '[{"title": "Subukang gamitin ulit", "detail": "I-donate, ibenta o ipaayos muna."}, {"title": "Magpakuha", "detail": "Ang barangay o lungsod ang nag-iiskedyul ng bulky pickup."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['mattress', 'wooden-chair']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('soiled-food-container', 'Soiled food container', 'Maruming lalagyan ng pagkain', array['takeout box', 'food container', 'lunch box', 'lalagyan', 'baonan', 'packed lunch']::text[], 'CMP-MIXED', null, 'residual', 'Scrape leftover food into the green bin, then put the container in the black bin.', 'Ilagay ang tirang pagkain sa berdeng basurahan, at ang lalagyan sa itim.', '[{"title": "Scrape the food", "detail": "Put leftover food in the green bin."}, {"title": "Sort the container", "detail": "Place the dirty container in the black bin."}]'::jsonb, '[{"title": "Alisin ang pagkain", "detail": "Ilagay ang tirang pagkain sa berdeng basurahan."}, {"title": "Itapon ang lalagyan", "detail": "Ilagay ang maruming lalagyan sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Food-soiled packaging can''t be recycled, but the food itself can be composted.', 'Hindi na mare-recycle ang lalagyang may mantsa ng pagkain, pero puwedeng i-compost ang pagkain.', '{}'::text[], 'soiled_food_container', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('solar-light', 'Solar garden light', 'Solar na ilaw', array['solar light', 'solar lamp', 'garden light', 'emergency light']::text[], 'LIG-LED', null, 'hazardous', 'Solar lights have a rechargeable battery. Bring them to an e-waste drop-off.', 'May rechargeable na baterya ang solar na ilaw. Dalhin sa e-waste drop-off.', '[{"title": "Keep it whole", "detail": "Don''t open or break it."}, {"title": "Bring it in", "detail": "E-waste drop-off or store take-back."}]'::jsonb, '[{"title": "Huwag sirain", "detail": "Huwag buksan o baklasin."}, {"title": "Dalhin", "detail": "Sa e-waste drop-off o take-back ng tindahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Built-in batteries can leak or overheat.', 'Puwedeng tumagas o uminit ang bateryang nasa loob.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['rechargeable-battery', 'led-bulb']::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('spray-can', 'Spray / aerosol can', 'Spray can', array['aerosol', 'spray', 'insect spray', 'deodorant spray', 'spray paint', 'baygon']::text[], 'MET-AERO', null, 'hazardous', 'Do not puncture or burn it. Place it in the red bin or a collection point.', 'Huwag butasin o sunugin. Ilagay sa pulang basurahan o sa collection point.', '[{"title": "Do not puncture it", "detail": "Pressurized cans can explode."}, {"title": "Sort it", "detail": "Place it in the red bin or a collection point."}]'::jsonb, '[{"title": "Huwag butasin", "detail": "Puwedeng sumabog ang may presyon na lata."}, {"title": "Ilagay", "detail": "Sa pulang basurahan o collection point."}]'::jsonb, 'Can explode under heat or pressure.', 'Puwedeng sumabog kapag nainitan o naipit.', '{}'::text[], '{}'::text[], 'Cans with product left are under pressure and can burst if crushed or heated.', 'May presyon pa ang lata kapag may laman, at puwedeng pumutok kapag naipit o nainitan.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Aerosol cans hold pressure and chemicals that are dangerous in regular waste.', 'May presyon at kemikal ang aerosol na delikado sa ordinaryong basura.', '{}'::text[], 'spray_can', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('straw', 'Straw', 'Straw', array['straw', 'plastic straw', 'drinking straw', 'istro']::text[], 'PLA-5', 5, 'residual', 'Place it in the black bin.', 'Ilagay sa itim na basurahan.', '[{"title": "Sort it", "detail": "Place the straw in the black bin."}, {"title": "Skip it next time", "detail": "Bring a reusable straw or drink without one."}]'::jsonb, '[{"title": "Itapon", "detail": "Ilagay ang straw sa itim na basurahan."}, {"title": "Iwasan sa susunod", "detail": "Magdala ng reusable na straw o uminom nang wala nito."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], array['Skip the straw, or bring a reusable one']::text[], array['Huwag nang gumamit ng straw, o magdala ng reusable']::text[], 'Straws are too small and light to be recycled.', 'Masyadong maliit at magaan ang straw para i-recycle.', '{}'::text[], 'straw', array['S-RA9003-22', 'S-QC-SP2876']::text[], 'draft', '{}'::text[], null),
  ('styrofoam', 'Styrofoam', 'Styro', array['styro', 'foam', 'styrofoam box', 'styrofoam cup', 'polystyrene']::text[], 'PLA-6', 6, 'residual', 'Empty any food, then place it in the black bin.', 'Alisin ang natirang pagkain, saka ilagay sa itim na basurahan.', '[{"title": "Empty it", "detail": "Scrape leftover food into the green bin."}, {"title": "Sort it", "detail": "Place the styrofoam in the black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ilagay ang tirang pagkain sa berdeng basurahan."}, {"title": "Ilagay", "detail": "Ang styro ay sa itim na basurahan."}]'::jsonb, null, null, array['Don''t burn it']::text[], array['Huwag sunugin']::text[], null, null, 'none', '{}'::text[], '{}'::text[], array['Bring your own lunch box for take-out']::text[], array['Magdala ng sariling baunan para sa take-out']::text[], 'Styrofoam is not recycled locally and breaks into small pieces that pollute.', 'Hindi nire-recycle dito ang styro, at nadudurog ito sa maliliit na pirasong nagpaparumi.', '{}'::text[], 'styrofoam', array['S-RA9003-22', 'S-QC-SP2876', 'S-QC-T2C']::text[], 'draft', '{}'::text[], null),
  ('syringe-needle', 'Syringe or needle', 'Hiringgilya o karayom', array['syringe', 'needle', 'karayom', 'hiringgilya', 'insulin needle', 'injection']::text[], 'MED-SHARP', null, 'hazardous', 'Never put loose needles in a bin. Seal them in a hard container and ask your barangay health centre or pharmacy.', 'Huwag maglagay ng karayom nang maluwag sa basurahan. Isara sa matigas na lalagyan at itanong sa health center o botika.', '[{"title": "Use a hard container", "detail": "A thick plastic bottle with a screw cap, like a detergent bottle."}, {"title": "Seal and label it", "detail": "Tape the cap and write SHARPS on it."}, {"title": "Ask where to bring it", "detail": "Your barangay health centre or pharmacy."}]'::jsonb, '[{"title": "Gumamit ng matigas na lalagyan", "detail": "Makapal na plastik na bote na may takip, tulad ng bote ng sabon."}, {"title": "Isara at lagyan ng label", "detail": "Lagyan ng tape ang takip at isulat ang SHARPS."}, {"title": "Itanong kung saan dadalhin", "detail": "Sa barangay health center o botika."}]'::jsonb, null, null, array['Don''t recap, bend or break needles']::text[], array['Huwag takpan ulit, baluktutin o baliin ang karayom']::text[], 'Used needles can injure and infect waste collectors and children.', 'Puwedeng makasugat at makahawa sa nangongolekta ng basura at sa bata ang gamit na karayom.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['lancet', 'medicine-syrup']::text[], null, array['S-RA9003-22', 'S-DOH-HCWM4']::text[], 'draft', '{}'::text[], null),
  ('t-shirt', 'T-shirt or clothes', 'Damit o t-shirt', array['damit', 'shirt', 'clothes', 'old clothes', 't-shirt', 'blouse']::text[], 'TEX-CLOTH', null, 'residual', 'Donate, repair or hand down clothes. Turn worn-out ones into rags before using the black bin.', 'I-donate, ipaayos o ipasa ang damit. Gawing basahan ang luma bago itapon sa itim.', '[{"title": "Wash it", "detail": "Donations should be clean."}, {"title": "Donate or repair", "detail": "Churches, charities and relatives take clothes."}, {"title": "Last resort", "detail": "Cut into rags, then the black bin."}]'::jsonb, '[{"title": "Labhan", "detail": "Dapat malinis ang ido-donate."}, {"title": "I-donate o ipaayos", "detail": "Tumatanggap ang simbahan, charity at kamag-anak."}, {"title": "Huling paraan", "detail": "Gawing basahan, saka sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away', 'Cut it into cleaning rags']::text[], array['Kung magagamit pa, ipamigay o i-donate', 'Gawing basahan']::text[], array['Buy fewer, longer-lasting clothes; try ukay-ukay']::text[], array['Bumili ng kaunti pero matibay; subukan ang ukay-ukay']::text[], null, null, array['jeans', 'rags']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('tea-bag', 'Tea bag', 'Tea bag', array['tea bag', 'tsaa', 'herbal tea bag']::text[], 'ORG-FOOD', null, 'biodegradable', 'Paper tea bags go in the green bin. Remove staples; nylon "silky" bags go in the black bin.', 'Ang papel na tea bag ay sa berde. Tanggalin ang staple; ang nylon na tea bag ay sa itim.', '[{"title": "Remove staples and tags", "detail": "Metal staples don''t compost."}, {"title": "Check the bag", "detail": "Paper: green bin. Nylon mesh: black bin."}]'::jsonb, '[{"title": "Tanggalin ang staple at tag", "detail": "Hindi nabubulok ang staple."}, {"title": "Suriin ang bag", "detail": "Papel: sa berde. Nylon: sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Use loose leaf tea']::text[], array['Gumamit ng loose leaf na tsaa']::text[], null, null, array['coffee-grounds']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('television', 'Television', 'Telebisyon', array['tv', 'television', 'crt tv', 'flat screen', 'monitor']::text[], 'BLK-APPL', null, 'hazardous', 'Donate a working TV. Bring broken ones to an e-waste collector; old tube TVs contain lead.', 'I-donate ang gumaganang TV. Dalhin ang sira sa e-waste collector; may lead ang lumang tube TV.', '[{"title": "Don''t open it", "detail": "Old TVs can hold an electric charge."}, {"title": "Hand it over", "detail": "Donate, or bring it to an e-waste collector."}]'::jsonb, '[{"title": "Huwag buksan", "detail": "Puwedeng may naiwang kuryente ang lumang TV."}, {"title": "Ibigay", "detail": "I-donate, o dalhin sa e-waste collector."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Old tube TVs contain leaded glass; all TVs have electronics that need e-waste handling.', 'May lead ang salamin ng lumang tube TV; lahat ng TV ay may electronics na kailangang e-waste.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['laptop']::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('test-kit', 'Rapid test kit', 'Rapid test kit', array['antigen test', 'pregnancy test', 'test kit', 'swab']::text[], 'MED-TEST', null, 'residual', 'Seal the used test parts in a bag and put it in the black bin.', 'Isara sa supot ang gamit na test at ilagay sa itim na basurahan.', '[{"title": "Bag it", "detail": "Put all parts in the bag provided."}, {"title": "Seal it", "detail": "Close the bag, then black bin."}]'::jsonb, '[{"title": "Isupot", "detail": "Ilagay lahat sa kasamang supot."}, {"title": "Isara", "detail": "Isara ang supot, saka sa itim."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['face-mask']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('tetra-pack', 'Tetra Pak / juice carton', 'Karton ng juice', array['tetra pak', 'juice box', 'milk carton', 'zesto', 'karton ng juice', 'drink box']::text[], 'CMP-CARTON', null, 'residual', 'Empty and flatten it, then place it in the black bin.', 'Ubusin at pitpitin, saka ilagay sa itim na basurahan.', '[{"title": "Empty it", "detail": "Finish or pour out the drink."}, {"title": "Flatten it", "detail": "Press it flat to save space."}, {"title": "Sort it", "detail": "Place it in the black bin, or a carton drop-off if your area has one."}]'::jsonb, '[{"title": "Ubusin", "detail": "Ubusin o itapon ang natirang inumin."}, {"title": "Pitpitin", "detail": "Pindutin para maging patag."}, {"title": "Ilagay", "detail": "Sa itim na basurahan, o sa carton drop-off kung mayroon sa inyo."}]'::jsonb, 'Some drop-off programs accept clean cartons. Check locally.', 'May mga programang tumatanggap ng malinis na karton. Alamin sa inyong lugar.', '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Cartons mix paper, plastic and aluminum layers that most junk shops don''t accept.', 'Ang karton ng juice ay pinaghalong papel, plastik at aluminyo kaya hindi ito binibili ng karamihan sa junk shop.', '{}'::text[], 'tetra_pack', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('toilet-bowl', 'Toilet bowl or sink', 'Inidoro o lababo', array['inidoro', 'toilet', 'sink', 'lababo', 'bathroom fixture']::text[], 'CER-TILE', null, 'residual', 'Too big for bins. Ask your barangay for bulky or construction waste pickup.', 'Masyadong malaki para sa basurahan. Itanong sa barangay ang pickup ng malalaking basura.', '[{"title": "Clean it", "detail": "Rinse it before collection."}, {"title": "Ask for pickup", "detail": "Your barangay handles bulky and construction waste."}]'::jsonb, '[{"title": "Linisin", "detail": "Banlawan bago kunin."}, {"title": "Magpakuha", "detail": "Ang barangay ang humahawak ng malalaking basura."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['floor-tile', 'construction-rubble']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('toothbrush', 'Toothbrush', 'Sipilyo', array['sipilyo', 'toothbrush', 'electric toothbrush head']::text[], 'CMP-MIXED', null, 'residual', 'Use old toothbrushes for cleaning, then put them in the black bin. Electric ones are e-waste.', 'Gamiting panlinis ang lumang sipilyo, saka ilagay sa itim. E-waste ang de-kuryente.', '[{"title": "Reuse it", "detail": "Great for scrubbing grout and shoes."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Gamitin ulit", "detail": "Magaling panlinis ng tiles at sapatos."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use it to clean tiles, shoes or tools']::text[], array['Gamiting panlinis ng tiles, sapatos o gamit']::text[], array['Try a bamboo toothbrush']::text[], array['Subukan ang kawayang sipilyo']::text[], null, null, array['toothpaste-tube']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('toothpaste-tube', 'Toothpaste tube', 'Tubo ng toothpaste', array['toothpaste', 'tube', 'ointment tube', 'lotion tube']::text[], 'CMP-TUBE', null, 'residual', 'Squeeze out what''s left and put the tube in the black bin.', 'Pigain ang natira at ilagay ang tubo sa itim na basurahan.', '[{"title": "Use it up", "detail": "Cut it open to get the last bit."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Ubusin", "detail": "Gupitin para makuha ang huling natira."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['toothbrush']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('towel', 'Towel', 'Tuwalya', array['tuwalya', 'towel', 'bath towel', 'face towel']::text[], 'TEX-HOME', null, 'residual', 'Animal shelters often welcome old towels. Otherwise, cut them into rags.', 'Madalas tumatanggap ng lumang tuwalya ang animal shelter. Kung hindi, gawing basahan.', '[{"title": "Wash it", "detail": "Clean before giving away."}, {"title": "Give or reuse", "detail": "Shelters, clinics or rags."}]'::jsonb, '[{"title": "Labhan", "detail": "Linisin bago ibigay."}, {"title": "Ibigay o gamitin", "detail": "Sa shelter, clinic o gawing basahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Give it to an animal shelter', 'Cut it into rags']::text[], array['Ibigay sa animal shelter', 'Gawing basahan']::text[], '{}'::text[], '{}'::text[], null, null, array['bedsheet', 'rags']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('underwear', 'Underwear', 'Panloob', array['brief', 'panty', 'bra', 'underwear', 'panloob']::text[], 'TEX-CLOTH', null, 'residual', 'Used underwear isn''t donated. Put it in the black bin, or use clean old ones as rags.', 'Hindi idino-donate ang gamit na panloob. Ilagay sa itim, o gawing basahan ang malinis na luma.', '[{"title": "Wash it", "detail": "Clean it if you''ll use it as a rag."}, {"title": "Sort it", "detail": "Black bin."}]'::jsonb, '[{"title": "Labhan", "detail": "Linisin kung gagawing basahan."}, {"title": "Itapon", "detail": "Sa itim na basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['t-shirt']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('used-cooking-oil', 'Used cooking oil', 'Gamit na mantika', array['mantika', 'cooking oil', 'used oil', 'grease', 'taba']::text[], 'ORG-OIL', null, 'residual', 'Let it cool, pour it into a sealed bottle, and never into the sink or drain.', 'Palamigin, ibuhos sa saradong bote, at huwag kailanman sa lababo o kanal.', '[{"title": "Let it cool", "detail": "Hot oil burns."}, {"title": "Bottle it", "detail": "Pour it into a bottle with a tight cap."}, {"title": "Sort it", "detail": "Give it to an oil collector, or put the sealed bottle in the black bin."}]'::jsonb, '[{"title": "Palamigin", "detail": "Nakapapaso ang mainit na mantika."}, {"title": "Ibote", "detail": "Ibuhos sa bote na mahigpit ang takip."}, {"title": "Itapon", "detail": "Ibigay sa kolektor ng mantika, o ilagay ang saradong bote sa itim."}]'::jsonb, null, null, array['Don''t pour it down the drain']::text[], array['Huwag ibuhos sa kanal o lababo']::text[], 'Oil poured into drains hardens, clogs pipes and canals, and adds to flooding.', 'Tumitigas ang mantikang ibinuhos sa kanal, bumabara sa tubo at kanal, at nagpapalala ng baha.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Quezon City bans food businesses from dumping grease and oil into drains and canals.', 'Ipinagbabawal ng Quezon City sa mga kainan ang pagtatapon ng mantika sa kanal.', array['cooking-oil-bottle']::text[], null, array['S-RA9003-22', 'S-QC-SP1804', 'S-QC-SP2691']::text[], 'draft', '{}'::text[], null),
  ('used-tissue', 'Used tissue', 'Gamit na tisyu', array['tissue', 'table napkin', 'paper towel', 'tisyu']::text[], 'PAP-TISSUE', null, 'biodegradable', 'Place in the green bin.', 'Ilagay sa berdeng basurahan.', '[{"title": "Check what it touched", "detail": "Plain tissue can be composted."}, {"title": "Sort it", "detail": "Use the green bin, or the black bin if it touched chemicals or blood."}]'::jsonb, '[{"title": "Alamin ang nadikit", "detail": "Puwedeng i-compost ang ordinaryong tisyu."}, {"title": "Ilagay", "detail": "Sa berde, o sa itim kung may kemikal o dugo."}]'::jsonb, 'Tissue used with chemicals or for blood goes in the black bin.', 'Ang tisyung ginamit sa kemikal o may dugo ay sa itim na basurahan.', '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Plain tissue is paper fiber and breaks down naturally.', 'Hibla ng papel ang ordinaryong tisyu kaya kusa itong nabubulok.', '{}'::text[], 'used_tissue', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('vape', 'Vape or e-cigarette', 'Vape', array['vape', 'e-cigarette', 'pod', 'disposable vape', 'e-cig']::text[], 'BAT-LI', null, 'hazardous', 'Vapes have a lithium battery and nicotine. Bring them to an e-waste or battery drop-off.', 'May lithium na baterya at nicotine ang vape. Dalhin sa e-waste o battery drop-off.', '[{"title": "Don''t puncture it", "detail": "Never crush, bend or open it."}, {"title": "Tape the contacts", "detail": "Cover metal contacts with tape."}, {"title": "Bring it in", "detail": "Battery or e-waste drop-off, never the regular bin."}]'::jsonb, '[{"title": "Huwag butasin", "detail": "Huwag durugin, baluktutin o buksan."}, {"title": "Takpan ng tape", "detail": "Takpan ng tape ang metal na contact."}, {"title": "Dalhin", "detail": "Sa battery o e-waste drop-off, hindi sa ordinaryong basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Vapes contain a lithium battery that can catch fire and leftover nicotine liquid that is toxic.', 'May lithium na baterya ang vape na puwedeng magliyab at natirang nicotine na nakalalason.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'RA 9003 lists household batteries and lead-acid batteries as special wastes that must be kept apart from other trash.', 'Itinuturing ng RA 9003 na special waste ang baterya sa bahay at ng sasakyan, kaya dapat itong ihiwalay.', array['power-bank', 'cigarette-butt']::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('vegetable-scraps', 'Vegetable scraps', 'Tira ng gulay', array['gulay', 'vegetable peel', 'trimmings', 'balat ng gulay']::text[], 'ORG-FOOD', null, 'biodegradable', 'Vegetable trimmings go in the green bin or compost.', 'Ang tira at balat ng gulay ay sa berdeng basurahan o compost.', '[{"title": "Keep it plastic-free", "detail": "Remove rubber bands and plastic."}, {"title": "Compost it", "detail": "Green bin or compost pile."}]'::jsonb, '[{"title": "Walang plastik", "detail": "Tanggalin ang goma at plastik."}, {"title": "I-compost", "detail": "Sa berdeng basurahan o compost."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Boil scraps into vegetable stock']::text[], array['Pakuluan ang tira para gawing sabaw']::text[], '{}'::text[], '{}'::text[], null, null, array['fruit-peel', 'food-scraps']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('washing-machine', 'Washing machine', 'Washing machine', array['washing machine', 'washer', 'dryer', 'labahan']::text[], 'BLK-APPL', null, 'hazardous', 'Try a repair shop. Otherwise, junk shops and e-waste collectors take old washers.', 'Subukan sa repair shop. Kung hindi, tinatanggap ng junk shop at e-waste collector ang lumang washing machine.', '[{"title": "Drain it", "detail": "Empty all water."}, {"title": "Repair or hand over", "detail": "Repair shop, junk shop or e-waste collector."}]'::jsonb, '[{"title": "Patuluin", "detail": "Alisin ang lahat ng tubig."}, {"title": "Ipaayos o ibigay", "detail": "Repair shop, junk shop o e-waste collector."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Appliances contain electronics, motors and metals that need proper recycling.', 'May electronics, motor at metal ang appliance na kailangang i-recycle nang tama.', null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'E-waste is hazardous waste under RA 6969, so it belongs with registered collectors, not in household bins.', 'Mapanganib na basura ang e-waste sa ilalim ng RA 6969, kaya sa rehistradong kolektor ito, hindi sa basurahan sa bahay.', array['refrigerator']::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('window-glass', 'Window glass', 'Salamin ng bintana', array['window glass', 'glass pane', 'jalousie', 'salamin', 'sheet glass']::text[], 'GLA-FLAT', null, 'residual', 'Flat glass is a different glass from bottles. Wrap it, label it BASAG and put it in the black bin.', 'Iba ang salamin ng bintana sa bote. Balutin, lagyan ng BASAG at ilagay sa itim na basurahan.', '[{"title": "Wrap it", "detail": "Wrap it in thick paper or cloth so no edge sticks out."}, {"title": "Label it", "detail": "Write BASAG (broken) on it."}, {"title": "Sort it", "detail": "Put it in the black bin, separate from other waste."}]'::jsonb, '[{"title": "Balutin", "detail": "Balutin sa makapal na papel o tela para walang lumabas na talim."}, {"title": "Lagyan ng label", "detail": "Isulat ang BASAG dito."}, {"title": "Itapon", "detail": "Ilagay sa itim na basurahan, hiwalay sa ibang basura."}]'::jsonb, 'Never put it in the blue bin with bottles.', 'Huwag ilagay sa asul kasama ng bote.', '{}'::text[], '{}'::text[], null, null, 'none', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, array['mirror', 'broken-glass']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('wire-hanger', 'Wire clothes hanger', 'Hanger na alambre', array['hanger', 'sabitan', 'wire hanger', 'coat hanger']::text[], 'MET-SCRAP', null, 'recyclable', 'Give hangers back to a laundry shop, or add them to your scrap metal.', 'Ibalik ang hanger sa laundry shop, o isama sa scrap na metal.', '[{"title": "Bundle them", "detail": "Twist several hangers together."}, {"title": "Give or sort", "detail": "Laundry shops often take them back."}]'::jsonb, '[{"title": "Pagsamahin", "detail": "Pilipitin nang magkakasama ang ilang hanger."}, {"title": "Ibigay o itapon", "detail": "Madalas tumatanggap ang laundry shop."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Give them back to a laundry shop']::text[], array['Ibalik sa laundry shop']::text[], '{}'::text[], '{}'::text[], null, null, array['scrap-wire']::text[], null, array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('wooden-chair', 'Chair or table', 'Upuan o mesa', array['chair', 'upuan', 'table', 'mesa', 'monobloc', 'office chair']::text[], 'BLK-FURN', null, 'residual', 'Repair or donate furniture. Broken pieces go to bulky pickup; small wood bits can go in the black bin.', 'Ipaayos o i-donate ang muwebles. Sa bulky pickup ang sira; ang maliliit na kahoy ay sa itim.', '[{"title": "Try to reuse it", "detail": "Donate, sell or repair first."}, {"title": "Ask for pickup", "detail": "Your barangay or city schedules bulky-waste collection."}]'::jsonb, '[{"title": "Subukang gamitin ulit", "detail": "I-donate, ibenta o ipaayos muna."}, {"title": "Magpakuha", "detail": "Ang barangay o lungsod ang nag-iiskedyul ng bulky pickup."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['If it''s still usable, donate it or give it away']::text[], array['Kung magagamit pa, ipamigay o i-donate']::text[], '{}'::text[], '{}'::text[], null, null, array['painted-wood', 'sofa']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('wooden-chopsticks', 'Disposable wooden chopsticks', 'Disposable na chopsticks', array['chopsticks', 'wooden chopsticks', 'hashi']::text[], 'WOO-RAW', null, 'biodegradable', 'Wooden or bamboo chopsticks go in the green bin. Plastic ones go in the black bin.', 'Ang kahoy o kawayang chopsticks ay sa berde. Ang plastik ay sa itim.', '[{"title": "Check the material", "detail": "Wood or bamboo?"}, {"title": "Sort it", "detail": "Green bin."}]'::jsonb, '[{"title": "Alamin ang materyal", "detail": "Kahoy o kawayan?"}, {"title": "Itapon", "detail": "Sa berdeng basurahan."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], array['Bring your own reusable chopsticks']::text[], array['Magdala ng sariling chopsticks']::text[], null, null, array['bamboo-skewer', 'plastic-utensil']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('wooden-crate', 'Wooden crate or pallet', 'Kahong kahoy o pallet', array['pallet', 'crate', 'fruit crate', 'kaing']::text[], 'WOO-RAW', null, 'biodegradable', 'Crates and pallets are easy to reuse. Give them away, or ask about bulky pickup.', 'Madaling gamitin ulit ang kahon at pallet. Ipamigay, o itanong ang bulky pickup.', '[{"title": "Remove nails", "detail": "Nails go to scrap metal."}, {"title": "Give it away", "detail": "Gardeners and vendors often want them."}]'::jsonb, '[{"title": "Tanggalin ang pako", "detail": "Sa scrap na metal ang pako."}, {"title": "Ipamigay", "detail": "Madalas gusto ito ng hardinero at tindero."}]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Make shelves or plant boxes', 'Give it to a vendor']::text[], array['Gawing istante o taniman', 'Ibigay sa tindero']::text[], '{}'::text[], '{}'::text[], null, null, array['painted-wood']::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null)
